  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, 'อธิบายกฎ ทฤษฎี หลักการ และปรากฏการณ์ต่าง ๆ โดยใช้ความรู้พื้นฐานทางวิทยาศาสตร์และคณิตศาสตร์ ในการปฏิบัติสหกิจศึกษา ที่สถานประกอบการได้ |   5 (ยอดเยี่ยม): อธิบายกฎ ทฤษฎี หลักการ และปรากฏการณ์ต่าง ๆ โดยใช้ความรู้พื้นฐานทางวิทยาศาสตร์และคณิตศาสตร์ได้อย่างครบถ้วนและถูกต้อง   4 (ดีมาก): อธิบายกฎ ทฤษฎี หลักการ และปรากฏการณ์ต่าง ๆ โดยใช้ความรู้พื้นฐานทางวิทยาศาสตร์และคณิตศาสตร์ได้อย่างครบถ้วนและถูกต้องเป็นส่วนใหญ่   3 (ดี): อธิบายกฎ ทฤษฎี หลักการ และปรากฏการณ์ต่าง ๆ โดยใช้ความรู้พื้นฐานทางวิทยาศาสตร์และคณิตศาสตร์ได้ถูกต้องเป็นส่วนใหญ่ แต่ขาดรายละเอียดปลีกย่อย   2 (พอใช้): อธิบายกฎ ทฤษฎี หลักการ และปรากฏการณ์ต่าง ๆ โดยใช้ความรู้พื้นฐานทางวิทยาศาสตร์และคณิตศาสตร์ได้ แต่ยังมีข้อผิดพลาดที่ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถอธิบายกฎ ทฤษฎี หลักการ และปรากฏการณ์ต่าง ๆ โดยใช้ความรู้พื้นฐานทางวิทยาศาสตร์และคณิตศาสตร์ได้', NULLIF('', ''), NULLIF('LO1', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, 'ประยุกต์ใช้ความรู้เฉพาะด้านของแต่ละวิชาเอก (วิชาเอกคณิตศาสตร์และสถิติ หรือวิชาเอกเคมี หรือวิชาเอกชีววิทยา หรือวิชาเอกฟิสิกส์) เพื่อการแก้ปัญหาทางวิทยาศาสตร์ ในการปฏิบัติสหกิจศึกษา ที่สถานประกอบการได้ |   5 (ยอดเยี่ยม): ประยุกต์ใช้ความรู้เฉพาะด้านของแต่ละวิชาเอก (วิชาเอกคณิตศาสตร์และสถิติ หรือวิชาเอกเคมี หรือวิชาเอกชีววิทยา หรือวิชาเอกฟิสิกส์) เพื่อการแก้ปัญหาทางวิทยาศาสตร์ ได้อย่างถูกต้อง เหมาะสม และนำไปใช้ประโยชน์ได้จริง   4 (ดีมาก): ประยุกต์ใช้ความรู้เฉพาะด้านของแต่ละวิชาเอก (วิชาเอกคณิตศาสตร์และสถิติ หรือวิชาเอกเคมี หรือวิชาเอกชีววิทยา หรือวิชาเอกฟิสิกส์) เพื่อการแก้ปัญหาทางวิทยาศาสตร์ได้อย่างถูกต้องและนำไปใช้ประโยชน์ได้จริง   3 (ดี): ประยุกต์ใช้ความรู้เฉพาะด้านของแต่ละวิชาเอก (วิชาเอกคณิตศาสตร์และสถิติ หรือวิชาเอกเคมี หรือวิชาเอกชีววิทยา หรือวิชาเอกฟิสิกส์) เพื่อการแก้ปัญหาทางวิทยาศาสตร์ได้ถูกต้องเป็นส่วนใหญ่   2 (พอใช้): ประยุกต์ใช้ความรู้เฉพาะด้านของแต่ละวิชาเอก (วิชาเอกคณิตศาสตร์และสถิติ หรือวิชาเอกเคมี หรือวิชาเอกชีววิทยา หรือวิชาเอกฟิสิกส์) เพื่อการแก้ปัญหาทางวิทยาศาสตร์ ได้แต่ยังมีข้อผิดพลาดที่ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถประยุกต์ใช้ความรู้เฉพาะด้านของแต่ละวิชาเอก (วิชาเอกคณิตศาสตร์และสถิติ หรือวิชาเอกเคมี หรือวิชาเอกชีววิทยา หรือวิชาเอกฟิสิกส์) เพื่อการแก้ปัญหาทางวิทยาศาสตร์ได้ (2)', NULLIF('', ''), NULLIF('LO2', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
