  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, 'ใช้เครื่องมือพื้นฐานเพื่อการทดลองและแก้ปัญหาทางวิทยาศาสตร์ ในการปฏิบัติสหกิจศึกษา ที่สถานประกอบการได้ |   5 (ยอดเยี่ยม): ใช้เครื่องมือพื้นฐานเพื่อการทดลองและแก้ปัญหาทางวิทยาศาสตร์ได้อย่างถูกต้อง และเหมาะสมกับงาน   4 (ดีมาก): ใช้เครื่องมือพื้นฐานเพื่อการทดลองและแก้ปัญหาทางวิทยาศาสตร์ ได้อย่างถูกต้องและเหมาะสมกับงานเป็นส่วนใหญ่   3 (ดี): ใช้เครื่องมือพื้นฐานเพื่อการทดลองและแก้ปัญหาทางวิทยาศาสตร์ได้ถูกต้องเป็นส่วนใหญ่   2 (พอใช้): ใช้เครื่องมือพื้นฐานเพื่อการทดลองและแก้ปัญหาทางวิทยาศาสตร์ได้แต่ยังมีข้อผิดพลาดที่ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถใช้เครื่องมือพื้นฐานเพื่อการทดลองและแก้ปัญหาทางวิทยาศาสตร์ได้', NULLIF('', ''), NULLIF('LO3', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, 'เลือกใช้เครื่องมือเพื่อการวิเคราะห์และทดสอบทางวิทยาศาสตร์ตามสาขาวิชาเอก ดังนี้ คณิตศาสตร์และสถิติ (สำหรับวิชาเอกคณิตศาสตร์และสถิติ) หรือเคมี (สำหรับวิชาเอกเคมี) หรือชีววิทยา (สำหรับวิชาเอกชีววิทยา) หรือฟิสิกส์ (สำหรับวิชาเอกฟิสิกส์) ในการปฏิบัติสหกิจศึกษา ที่สถานประกอบการได้ |   5 (ยอดเยี่ยม): เลือกใช้เครื่องมือเพื่อการวิเคราะห์และทดสอบทางวิทยาศาสตร์ตามสาขาวิชาเอกได้อย่างถูกต้อง เหมาะสม และนำไปใช้ประโยชน์ได้จริง   4 (ดีมาก): เลือกใช้เครื่องมือเพื่อการวิเคราะห์และทดสอบทางวิทยาศาสตร์ตามสาขาวิชาเอกได้อย่างถูกต้องและนำไปใช้ประโยชน์ได้จริง   3 (ดี): เลือกใช้เครื่องมือเพื่อการวิเคราะห์และทดสอบทางวิทยาศาสตร์ตามสาขาวิชาเอกได้ถูกต้องเป็นส่วนใหญ่   2 (พอใช้): เลือกใช้เครื่องมือเพื่อการวิเคราะห์และทดสอบทางวิทยาศาสตร์ตามสาขาวิชาเอกได้แต่ยังมีข้อผิดพลาดที่ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถเลือกใช้เครื่องมือเพื่อการวิเคราะห์และทดสอบทางวิทยาศาสตร์ตามสาขาวิชาเอกได้', NULLIF('', ''), NULLIF('LO4', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, 'มีทักษะในการทำวิจัย เพื่อแก้ปัญหาทางวิทยาศาสตร์ ในการปฏิบัติสหกิจศึกษา ที่สถานประกอบการได้ |   5 (ยอดเยี่ยม): มีทักษะในการทำวิจัย เพื่อแก้ปัญหาทางวิทยาศาสตร์ได้อย่างถูกต้อง เหมาะสม และใช้ได้จริงในสถานประกอบการ   4 (ดีมาก): มีทักษะในการทำวิจัย เพื่อแก้ปัญหาทางวิทยาศาสตร์ได้อย่างถูกต้อง   3 (ดี): มีทักษะในการทำวิจัย เพื่อแก้ปัญหาทางวิทยาศาสตร์ได้ถูกต้องเป็นส่วนใหญ่   2 (พอใช้): มีทักษะในการทำวิจัย เพื่อแก้ปัญหาทางวิทยาศาสตร์ได้แต่ยังมีข้อผิดพลาดที่ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่มีทักษะในการทำวิจัย เพื่อแก้ปัญหาทางวิทยาศาสตร์ได้', NULLIF('', ''), NULLIF('LO5', ''), 'single_choice'::question_type, true, 3)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, 'มีทักษะการสื่อสารภาษาไทยหรือภาษาต่างประเทศ ในการสื่อสารวิทยาศาสตร์ ทั้งการฟัง พูด อ่าน เขียน และนำเสนอผลงานตามวัตถุประสงค์ ในการปฏิบัติสหกิจศึกษา ที่สถานประกอบการได้ |   5 (ยอดเยี่ยม): มีทักษะการสื่อสารภาษาไทยหรือภาษาต่างประเทศ ในการสื่อสารวิทยาศาสตร์ ทั้งการฟัง พูด อ่าน เขียน และนำเสนอผลงานตามวัตถุประสงค์ได้อย่างถูกต้อง เหมาะสม และใช้ได้จริงในสถานประกอบการ   4 (ดีมาก): มีทักษะการสื่อสารภาษาไทยหรือภาษาต่างประเทศ ในการสื่อสารวิทยาศาสตร์ ทั้งการฟัง พูด อ่าน เขียน และนำเสนอผลงานตามวัตถุประสงค์ได้อย่างถูกต้อง   3 (ดี): มีทักษะการสื่อสารภาษาไทยหรือภาษาต่างประเทศ ในการสื่อสารวิทยาศาสตร์ ทั้งการฟัง พูด อ่าน เขียน และนำเสนอผลงานตามวัตถุประสงค์ได้ถูกต้องเป็นส่วนใหญ่   2 (พอใช้): มีทักษะการสื่อสารภาษาไทยหรือภาษาต่างประเทศ ในการสื่อสารวิทยาศาสตร์ ทั้งการฟัง พูด อ่าน เขียน และนำเสนอผลงานตามวัตถุประสงค์ได้แต่ยังมีข้อผิดพลาดที่ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่มีทักษะการสื่อสารภาษาไทยหรือภาษาต่างประเทศ ในการสื่อสารวิทยาศาสตร์ ทั้งการฟัง พูด อ่าน เขียน และนำเสนอผลงานตามวัตถุประสงค์ได้', NULLIF('', ''), NULLIF('LO6', ''), 'single_choice'::question_type, true, 4)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, 'ใช้เทคโนโลยีสารสนเทศในการค้นคว้า แสวงหาความรู้ และประยุกต์ในงานด้านวิทยาศาสตร์และงานสำนักงานได้อย่างรู้เท่าทัน ท่ามกลางการเปลี่ยนแปลงในยุคดิจิทัล ในการปฏิบัติสหกิจศึกษา ที่สถานประกอบการได้ |   5 (ยอดเยี่ยม): ใช้เทคโนโลยีสารสนเทศในการค้นคว้า แสวงหาความรู้ และประยุกต์ในงานด้านวิทยาศาสตร์และงานสำนักงานได้อย่างรู้เท่าทัน ท่ามกลางการเปลี่ยนแปลงในยุคดิจิทัลได้อย่างถูกต้อง และเหมาะสม   4 (ดีมาก): ใช้เทคโนโลยีสารสนเทศในการค้นคว้า แสวงหาความรู้ และประยุกต์ในงานด้านวิทยาศาสตร์และงานสำนักงานได้อย่างรู้เท่าทัน ท่ามกลางการเปลี่ยนแปลงในยุคดิจิทัลได้อย่างถูกต้อง   3 (ดี): ใช้เทคโนโลยีสารสนเทศในการค้นคว้า แสวงหาความรู้ และประยุกต์ในงานด้านวิทยาศาสตร์และงานสำนักงานได้อย่างรู้เท่าทัน ท่ามกลางการเปลี่ยนแปลงในยุคดิจิทัลได้ถูกต้องเป็นส่วนใหญ่   2 (พอใช้): ใช้เทคโนโลยีสารสนเทศในการค้นคว้า แสวงหาความรู้ และประยุกต์ในงานด้านวิทยาศาสตร์และงานสำนักงานได้อย่างรู้เท่าทัน ท่ามกลางการเปลี่ยนแปลงในยุคดิจิทัลได้แต่ยังมีข้อผิดพลาดที่ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถใช้เทคโนโลยีสารสนเทศในการค้นคว้า แสวงหาความรู้ และประยุกต์ในงานด้านวิทยาศาสตร์และงานสำนักงานได้อย่างรู้เท่าทัน ท่ามกลางการเปลี่ยนแปลงในยุคดิจิทัลได้ (3)', NULLIF('', ''), NULLIF('LO7', ''), 'single_choice'::question_type, true, 5)
  RETURNING id INTO q_id;
