  VALUES (t_id, 'ด้านจริยธรรม (Ethics)', NULLIF('', ''), 'ethics'::domain_type, 7)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนมีความซื่อสัตย์ ยึดมั่นในจรรยาบรรณแห่งวิชาชีพ และแสดงความกตัญญูต่อสถานประกอบการ |   5 (ยอดเยี่ยม): ซื่อสัตย์ ปฏิบัติตามกฎระเบียบ   มีความยึดมั่นในจรรยาบรรณแห่งวิชาชีพ และแสดงความกตัญญูต่อสถานประกอบการอย่างเคร่งครัด   4 (ดีมาก): ซื่อสัตย์ ปฏิบัติตามกฎระเบียบ         มีความยึดมั่นในจรรยาบรรณแห่งวิชาชีพ และแสดงความกตัญญูต่อสถานประกอบการได้ในระดับดี แม้จะมีข้อผิดพลาดเล็กน้อย   3 (ดี): ซื่อสัตย์ ปฏิบัติตามกฎระเบียบ มีความยึดมั่นในจรรยาบรรณแห่งวิชาชีพ และแสดงความกตัญญูต่อสถานประกอบการได้ในระดับพื้นฐาน                    มีข้อผิดพลาดเล็กน้อยและมีข้อปรับปรุงในบางส่วน   2 (พอใช้): ซื่อสัตย์ ปฏิบัติตามกฎระเบียบ         มีความยึดมั่นในจรรยาบรรณแห่งวิชาชีพ และแสดงความกตัญญูต่อสถานประกอบการในบางโอกาส   1 (ต้องปรับปรุง): ไม่ปฏิบัติตามกฎระเบียบ และแสดงถึงความขาดความรับผิดชอบในงานอย่างชัดเจน (4)', NULLIF('', ''), NULLIF('LO10', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  -- Section: ด้านลักษณะบุคคล
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านลักษณะบุคคล', NULLIF('', ''), 'character'::domain_type, 8)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนมีความรับผิดชอบต่อผลกระทบของงานวิศวกรรมที่ดำเนินการในสถานประกอบการ และสามารถประเมินผลกระทบต่อสังคมและสิ่งแวดล้อม |   5 (ยอดเยี่ยม): รับผิดชอบต่อผลกระทบของงานวิศวกรรมที่ดำเนินการในสถานประกอบการ และสามารถประเมินผลกระทบต่อสังคมและสิ่งแวดล้อมได้เป็นอย่างถูกต้องครบถ้วน   4 (ดีมาก): รับผิดชอบต่อผลกระทบของงานวิศวกรรมที่ดำเนินการในสถานประกอบการ และสามารถประเมินผลกระทบต่อสังคมและสิ่งแวดล้อมได้เป็นอย่างถูกต้อง   3 (ดี): รับผิดชอบต่อผลกระทบของงานวิศวกรรมที่ดำเนินการในสถานประกอบการ และสามารถประเมินผลกระทบต่อสังคมและสิ่งแวดล้อมได้ในระดับดี แม้จะมีข้อบกพร่องเล็กน้อยแต่ไม่กระทบงานที่ได้รับผิดชอบ   2 (พอใช้): รับผิดชอบต่อผลกระทบของงานวิศวกรรมที่ดำเนินการในสถานประกอบการ และสามารถประเมินผลกระทบต่อสังคมและสิ่งแวดล้อมได้เพียงบางส่วน   1 (ต้องปรับปรุง): ไม่มีความรับผิดชอบต่อผลกระทบของงานวิศวกรรม', NULLIF('', ''), NULLIF('LO11', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถทำงานร่วมกับผู้อื่นในสถานประกอบการอย่างมีประสิทธิภาพ ทั้งในบทบาทผู้นำและผู้ตาม พร้อมทั้งแสดงความมีวินัยและการปรับตัวตามสถานการณ์ |   5 (ยอดเยี่ยม): ทำงานร่วมกับผู้อื่นในสถานประกอบการอย่างมีประสิทธิภาพ ทั้งในบทบาทผู้นำและผู้ตาม พร้อมทั้งแสดงความมีวินัยและการปรับตัวตามสถานการณ์   4 (ดีมาก): ทำงานร่วมกับผู้อื่นในสถานประกอบการได้เป็นอย่างดี ทั้งในบทบาทผู้นำและผู้ตาม พร้อมทั้งแสดงความมีวินัยและการปรับตัวตามสถานการณ์   3 (ดี): ทำงานร่วมกับผู้อื่นในสถานประกอบการได้ในระดับพื้นฐาน ทั้งในบทบาทผู้นำและผู้ตาม พร้อมทั้งแสดงความมีวินัยและการปรับตัวตามสถานการณ์ แต่ต้องได้รับคำแนะนำหรือแนวทางในการทำงาน   2 (พอใช้): ทำงานร่วมกับผู้อื่นในสถานประกอบการได้ในบางส่วน ทั้งในบทบาทผู้นำและผู้ตาม พร้อมทั้งแสดงความมีวินัยและการปรับตัวตามสถานการณ์แต่จำเป็นต้องได้รับคำแนะนำหรือแนวทางในการทำงาน   1 (ต้องปรับปรุง): ไม่สามารถทำงานร่วมกับทีมได้อย่างเหมาะสม', NULLIF('', ''), NULLIF('LO12', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
END $$;

