  -- Section: ด้านความรู้ (Knowledge)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านความรู้ (Knowledge)', NULLIF('', ''), 'knowledge'::domain_type, 1)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': 	ประยุกต์ใช้ความรู้ทางด้านคณิตศาสตร์ พื้นฐานทางด้านวิศวกรรมศาสตร์ ในการกำหนดกรอบความคิด กระบวนการ หรือระบบงานสำหรับการวิเคราะห์ แก้ไขปัญหา และประเมินผลงานและปัญหาทางวิศวกรรม วิศวกรรมในการทำงานได้อย่างถูกต้อง |  5 (ยอดเยี่ยม): ประยุกต์ใช้ความรู้ทางด้านคณิตศาสตร์ พื้นฐานทางด้านวิศวกรรมศาสตร์ ในการกำหนดกรอบความคิด กระบวนการ หรือระบบงานสำหรับการวิเคราะห์ แก้ไขปัญหา และประเมินผลงานและปัญหาทางวิศวกรรมในการทำงานได้อย่างถูกต้อง  4 (ดีมาก): ประยุกต์ใช้ความรู้ทางด้านคณิตศาสตร์ พื้นฐานทางด้านวิศวกรรมศาสตร์ ในการกำหนดกรอบความคิด กระบวนการ หรือระบบงานสำหรับการวิเคราะห์ แก้ไขปัญหา และประเมินผลงานและปัญหาทางวิศวกรรมในการทำงานได้ไม่กระทบต่อคุณภาพโดยรวม  3 (ดี): ประยุกต์ใช้ความรู้ทางด้านคณิตศาสตร์ พื้นฐานทางด้านวิศวกรรมศาสตร์ ในการกำหนดกรอบความคิด กระบวนการ หรือระบบงานสำหรับการวิเคราะห์ แก้ไขปัญหา และประเมินผลงานและปัญหาทางวิศวกรรมโดยยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): ประยุกต์ใช้ความรู้ทางด้านคณิตศาสตร์ พื้นฐานทางด้านวิศวกรรมศาสตร์ ในการกำหนดกรอบความคิด กระบวนการ หรือระบบงานสำหรับการวิเคราะห์ แก้ไขปัญหา และประเมินผลงานและปัญหาทางวิศวกรรม โดยต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถประยุกต์ใช้ความรู้ทางด้านคณิตศาสตร์ พื้นฐานทางด้านวิศวกรรมศาสตร์ ในการกำหนดกรอบความคิด กระบวนการ หรือระบบงานสำหรับการวิเคราะห์ แก้ไขปัญหา และประเมินผลงานและปัญหาทางวิศวกรรม วิศวกรรมในการทำงานได้อย่างถูกต้อง', NULLIF('', ''), NULLIF('LO1', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': อธิบาย และประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมโยธาต่อบริบทของทางสังคม ชีวอนามัย ความปลอดภัย กฎหมาย สิ่งแวดล้อม และการพัฒนาที่ยั่งยืน |   5 (ยอดเยี่ยม): อธิบาย และประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมโยธาต่อบริบทของทางสังคม ชีวอนามัย ความปลอดภัย กฎหมาย สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนในการทำงานได้อย่างถูกต้อง   4 (ดีมาก): อธิบาย และประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมโยธาต่อบริบทของทางสังคม ชีวอนามัย ความปลอดภัย กฎหมาย สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนในการทำงานได้ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): อธิบาย และประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมโยธาต่อบริบทของทางสังคม ชีวอนามัย ความปลอดภัย กฎหมาย สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนโดยยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): อธิบาย และประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมโยธาต่อบริบทของทางสังคม ชีวอนามัย ความปลอดภัย กฎหมาย สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนโดยต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถอธิบาย และประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมโยธาต่อบริบทของทางสังคม ชีวอนามัย ความปลอดภัย กฎหมาย สิ่งแวดล้อม และการพัฒนาที่ยั่งยืน', NULLIF('', ''), NULLIF('LO2', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
