  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': คิดเป็นระบบอย่างมีวิจารณญาณมีเหตุผล รับผิดชอบต่อสังคมและรักษาสิ่งแวดล้อม |  5 (ยอดเยี่ยม): คิดเป็นระบบอย่างมีวิจารณญาณมีเหตุผล รับผิดชอบต่อสังคมและรักษาสิ่งแวดล้อม  4 (ดีมาก): คิดเป็นระบบอย่างมีวิจารณญาณมีเหตุผล รับผิดชอบต่อสังคมและรักษาสิ่งแวดล้อมได้บางส่วนไม่กระทบต่อคุณภาพโดยรวม  3 (ดี): คิดเป็นระบบอย่างมีวิจารณญาณมีเหตุผล รับผิดชอบต่อสังคมและรักษาสิ่งแวดล้อมโดยยังขาดความสมบูรณ์ในบางส่วน  2 (พอใช้): คิดเป็นระบบอย่างมีวิจารณญาณมีเหตุผล รับผิดชอบต่อสังคมและรักษาสิ่งแวดล้อมโดยต้องการคำแนะนำอย่างใกล้ชิด  1 (ต้องปรับปรุง): ไม่สามารถคิดเป็นระบบอย่างมีวิจารณญาณมีเหตุผล รับผิดชอบต่อสังคมและรักษาสิ่งแวดล้อม', NULLIF('', ''), NULLIF('LO10', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
