  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, 'สามารถทำงานเป็นทีมโดยปฏิบัติตนเป็นผู้นำ และ/หรือ ในฐานะสมาชิกของกลุ่มร่วมกับผู้อื่นที่มีความหลากหลายในสหสาขาวิชาได้ |  5 (ยอดเยี่ยม): สามารถทำงานเป็นทีมโดยปฏิบัติตนเป็นผู้นำ และ/หรือ ในฐานะสมาชิกของกลุ่มร่วมกับผู้อื่นที่มีความหลากหลายในสหสาขาวิชาได้  4 (ดีมาก): สามารถทำงานเป็นทีมโดยปฏิบัติตนเป็นผู้นำ และ/หรือ ในฐานะสมาชิกของกลุ่มร่วมกับผู้อื่นที่มีความหลากหลายในสหสาขาวิชาได้บางส่วนไม่กระทบต่อคุณภาพโดยรวม  3 (ดี): สามารถทำงานเป็นทีมโดยปฏิบัติตนเป็นผู้นำ และ/หรือ ในฐานะสมาชิกของกลุ่มร่วมกับผู้อื่นที่มีความหลากหลายในสหสาขาวิชาได้ในการทำงานตามวิชาชีพ โดยยังขาดความสมบูรณ์ในบางส่วน  2 (พอใช้): สามารถทำงานเป็นทีมโดยปฏิบัติตนเป็นผู้นำ และ/หรือ ในฐานะสมาชิกของกลุ่มร่วมกับผู้อื่นที่มีความหลากหลายในสหสาขาวิชาได้โดยต้องการคำแนะนำอย่างใกล้ชิด  1 (ต้องปรับปรุง): ไม่สามารถทำงานเป็นทีมโดยปฏิบัติตนเป็นผู้นำ และ/หรือ ในฐานะสมาชิกของกลุ่มร่วมกับผู้อื่นที่มีความหลากหลายในสหสาขาวิชาได้', NULLIF('', ''), NULLIF('LO11', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
END $$;

DO $$ DECLARE t_id uuid; s_id uuid; q_id uuid; BEGIN
