  SELECT sd.program_id, 'หลักสูตรนิติศาสตรบัณฑิต', NULLIF('', ''), 'draft', 'draft'::assessment_status, '0.1', sd.id, 1.0, true
  FROM public.assessment_source_documents sd WHERE sd.filename = 'หลักสูตรนิติศาสตรบัณฑิต หลักสูตรปรับปรุง ปีการศึกษา ๒๕๖๗  .docx'
