  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ':  ผู้เรียนสามารถปฏิบัติงานด้วยความรับผิดชอบและคำนึงถึงจริยธรรมในวิชาชีพ โดยพิจารณาผลกระทบต่อเศรษฐกิจ สังคม และสิ่งแวดล้อม', NULLIF('', ''), NULLIF('LO5', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  -- Section: ด้านลักษณะบุคคล
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านลักษณะบุคคล', NULLIF('', ''), 'character'::domain_type, 4)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถทำงานร่วมกับทีม ได้อย่างมีประสิทธิภาพ พร้อมทั้งแสดงบทบาทความเป็นผู้นำและการร่วมมือที่ดีตามสถานะของตนเองในทีม ผลการเรียนรู้ที่คาดหวัง | ผลการประเมิน (1)', NULLIF('', ''), NULLIF('LO6', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  -- Section: ด้านความรู้ (Knowledge)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านความรู้ (Knowledge)', NULLIF('', ''), 'knowledge'::domain_type, 5)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ':ผู้เรียนสามารถระบุและแก้ปัญหาที่ซับซ้อนในงานที่ได้รับมอบหมายในสถานประกอบการ โดยประยุกต์หลักการทางวิชาชีพทางกฎหมายได้อย่างเหมาะสม |   5 (ยอดเยี่ยม): ระบุและแก้ปัญหาที่ซับซ้อนได้อย่างครบถ้วน พร้อมเสนอแนวทางแก้ไขที่สร้างสรรค์ มีประสิทธิภาพสูง และตอบโจทย์ความต้องการของสถานประกอบการได้อย่างสมบูรณ์   4 (ดีมาก): ระบุและแก้ปัญหาได้ในระดับดี พร้อมเสนอแนวทางแก้ไขที่เหมาะสม แม้จะมีข้อบกพร่องเล็กน้อยแต่ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): ระบุปัญหาและแก้ไขได้ในระดับพื้นฐาน แต่ข้อเสนอแนวทางแก้ไขยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): ระบุปัญหาได้บางส่วน แต่ไม่สามารถแก้ไขได้อย่างเหมาะสม ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถระบุหรือแก้ปัญหาได้ และไม่มีข้อเสนอแนะแนวทางแก้ไข (2)', NULLIF('', ''), NULLIF('LO1', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  -- Section: ด้านทักษะ (Skills)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านทักษะ (Skills)', NULLIF('', ''), 'skills'::domain_type, 6)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถรวบรวม วิเคราะห์ และแปลผลข้อมูลจากการปฏิบัติงานในสถานประกอบการได้ |   5 (ยอดเยี่ยม): วิเคราะห์ข้อมูลได้อย่างถูกต้อง ครบถ้วน และแปลผลได้ชัดเจน พร้อมข้อสรุปที่นำไปใช้ได้จริง   4 (ดีมาก): วิเคราะห์ข้อมูลได้ดีในระดับที่เหมาะสม พร้อมข้อสรุปที่เป็นประโยชน์ แม้จะมีข้อผิดพลาดเล็กน้อย   3 (ดี): วิเคราะห์ข้อมูลได้ในระดับพื้นฐาน แต่ข้อสรุปยังขาดความชัดเจนและความสมบูรณ์ในบางส่วน   2 (พอใช้): วิเคราะห์ข้อมูลได้เพียงบางส่วน และข้อสรุปยังไม่ชัดเจน ต้องการคำแนะนำเพิ่มเติม   1 (ต้องปรับปรุง): ไม่สามารถวิเคราะห์ข้อมูลหรือแปลผลได้', NULLIF('', ''), NULLIF('LO2', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถสื่อสารกับเพื่อนร่วมงานและบุคคลในสถานประกอบการด้วยภาษาอังกฤษได้ |   5 (ยอดเยี่ยม): สื่อสารได้ชัดเจน เข้าใจง่าย ใช้ภาษาอังกฤษได้อย่างเหมาะสมกับสถานการณ์   4 (ดีมาก): สื่อสารได้ดีในระดับที่เหมาะสม แม้จะมีข้อผิดพลาดเล็กน้อยที่ไม่กระทบต่อการทำงาน   3 (ดี): สื่อสารได้ในระดับพื้นฐาน แต่ยังมีข้อผิดพลาดหรือจุดที่ไม่ชัดเจนในบางสถานการณ์   2 (พอใช้): สื่อสารได้บ้าง แต่ยังไม่เหมาะสมกับสถานการณ์หรือมีข้อผิดพลาดที่ส่งผลต่อการทำงาน   1 (ต้องปรับปรุง): ไม่สามารถสื่อสารได้อย่างเหมาะสมในสถานการณ์จริง', NULLIF('', ''), NULLIF('LO3', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถเรียนรู้และพัฒนาทักษะใหม่ที่เกี่ยวข้องกับงานในสถานประกอบการด้วยตนเอง |   5 (ยอดเยี่ยม): นักศึกษาสามารถเรียนรู้ทักษะใหม่ได้อย่างรวดเร็วและนำไปประยุกต์ใช้ในงานได้อย่างมีประสิทธิภาพ มีการริเริ่มในการศึกษาข้อมูลเพิ่มเติมด้วยตัวเอง และแสดงผลลัพธ์ที่ชัดเจน   4 (ดีมาก): นักศึกษาสามารถเรียนรู้ทักษะใหม่ได้ดี และสามารถนำไปใช้ในงานได้ในระดับที่เหมาะสม แม้จะมีการปรับปรุงในบางส่วน   3 (ดี): นักศึกษาสามารถเรียนรู้ทักษะใหม่ได้ในระดับพื้นฐาน และเริ่มต้นนำไปใช้ในงานบางส่วน แต่ยังขาดความสมบูรณ์   2 (พอใช้): นักศึกษาสามารถเรียนรู้ทักษะใหม่ได้ในระดับที่จำกัด และยังไม่สามารถประยุกต์ใช้ได้อย่างเหมาะสม   1 (ต้องปรับปรุง): นักศึกษาไม่สามารถเรียนรู้ทักษะใหม่ได้ด้วยตนเอง และขาดความพยายามในการพัฒนาตนเอง (3)', NULLIF('', ''), NULLIF('LO4', ''), 'single_choice'::question_type, true, 3)
  RETURNING id INTO q_id;
  -- Section: ด้านจริยธรรม (Ethics)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านจริยธรรม (Ethics)', NULLIF('', ''), 'ethics'::domain_type, 7)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถปฏิบัติงานด้วยความรับผิดชอบและคำนึงถึงจริยธรรมในวิชาชีพ |   5 (ยอดเยี่ยม): ปฏิบัติตามกฎระเบียบทุกข้ออย่างเคร่งครัด พร้อมแสดงความซื่อสัตย์และความรับผิดชอบอย่างชัดเจน   4 (ดีมาก): ปฏิบัติตามกฎระเบียบส่วนใหญ่ และแสดงความรับผิดชอบในงานได้ดี แม้จะมีข้อผิดพลาดเล็กน้อย   3 (ดี): ปฏิบัติตามกฎระเบียบได้ในระดับพื้นฐาน แต่ยังต้องการการปรับปรุงในบางส่วน   2 (พอใช้): ปฏิบัติตามกฎระเบียบได้เพียงบางข้อ และยังมีการละเลยหรือผิดพลาดบ้าง   1 (ต้องปรับปรุง): ไม่ปฏิบัติตามกฎระเบียบ และแสดงถึงความขาดความรับผิดชอบในงาน (4)', NULLIF('', ''), NULLIF('LO5', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  -- Section: ด้านลักษณะบุคคล
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านลักษณะบุคคล', NULLIF('', ''), 'character'::domain_type, 8)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถทำงานร่วมกับทีม ได้อย่างมีประสิทธิภาพ พร้อมทั้งแสดงบทบาทความเป็นผู้นำและการร่วมมือที่ดี |   5 (ยอดเยี่ยม): มีบทบาทสำคัญในทีม ช่วยสร้างสภาพแวดล้อมการทำงานที่ดี และแสดงภาวะผู้นำได้อย่างชัดเจน   4 (ดีมาก): ทำงานร่วมกับทีมได้ดีในระดับที่เหมาะสม และปฏิบัติงานตามบทบาทที่ได้รับอย่างสมบูรณ์   3 (ดี): ทำงานร่วมกับทีมได้ในระดับพื้นฐาน แต่ยังต้องปรับปรุงในบางด้าน   2 (พอใช้): ทำงานร่วมกับทีมได้บางส่วน แต่มีปัญหาในการสื่อสารหรือการมีส่วนร่วม   1 (ต้องปรับปรุง): ไม่สามารถทำงานร่วมกับทีมได้อย่างเหมาะสม', NULLIF('', ''), NULLIF('LO6', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
END $$;

DO $$ DECLARE t_id uuid; s_id uuid; q_id uuid; BEGIN
  -- Create template
  INSERT INTO public.evaluation_templates (program_id, name, title_en, status, status_enum, version_label, source_document_id, extraction_confidence, needs_review)
  SELECT sd.program_id, 'หลักสูตรบริหารธุรกิจบัณฑติ สาขาศิลปะการประกอบอาหารอย่างมืออาชีพ', NULLIF('heat cooking methods, and combination cooking methods) ตามกฎกระทรวงสาธารณสุข', ''), 'draft', 'draft'::assessment_status, '0.1', sd.id, 1.0, true
  FROM public.assessment_source_documents sd WHERE sd.filename = 'LO สหกิจหลักสูตรศิลปะการประกอบอาชีพ.pdf'
  RETURNING id INTO t_id;
  IF t_id IS NULL THEN RETURN; END IF;
  -- Section: ด้านความรู้ (Knowledge)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านความรู้ (Knowledge)', NULLIF('', ''), 'knowledge'::domain_type, 1)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': สามารถประยุกต์ใช้องค์ความรู้ ยอดเยี่ยม (5) - การจัดการวัตถุดิบ: วางแผนและจัดการวัตถุดิบได้อย่างมีประสิทธิภาพสูงสุด โดยคำนึงถึงคุณภาพ ต้นทุน และความยั่งยืน - การเตรียมและประกอบอาหาร: ดำเนินการเตรียมและประกอบอาหารได้อย่างถูกต้องตามมาตรฐานสากล มีความคิดสร้างสรรค์ และสามารถ ทางด้านการจัดการวัตถุดิบ การเตรียม ปรับสูตรอาหารให้เหมาะสมกับสถานการณ ์ การประกอบอาหารและการบริหารและ - การบริหารจัดการ: วางแผนและจัดการงานในครัวและธุรกิจอาหารได้อย่างมีประสิทธิภาพ โดยใช้เครื่องมือและเทคนิคการบริหารที่ทันสมัย - การประยุกต์องค์ความรู้: สามารถประยุกต์ใช้ความรเู้พื่อแก้ปัญหาและพัฒนานวัตกรรมในอุตสาหกรรมบริการอาหารได้อย่างมีประสิทธิผล การจัดการ เพื่อบริหารจัดการธุรกิจใน', NULLIF('', ''), NULLIF('LO1', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('Very Good', ''), NULLIF('(4) - การจัดการวัตถุดิบ: จัดการวัตถุดิบได้ดีในด้านคุณภาพและต้นทุน แต่ยังมีข้อจำกัดเล็กน้อยในด้านการลดของเสียหรือการใช้ทรัพยากรให้เกิด อุตสาหกรรมบริการอาหารได้ ประโยชน์สูงสุด - การเตรียมและประกอบอาหาร: เตรียมและประกอบอาหารได้ตามมาตรฐาน มีข้อผิดพลาดเล็กน้อย และสามารถปรับปรุงได้ - การบริหารจัดการ: จัดการงานในครัวและธรุ กิจอาหารได้ดี แต่ยังขาดการใช้เทคนิคขั้นสูงหรือการพัฒนาเพมิ่ เติม - การประยุกต์องค์ความรู้: สามารถประยุกต์ใช้ความรเู้พื่อพัฒนาธรุ กิจได้ดี แต่ยังมีพื้นที่สำหรับการปรับปรุงหรือสร้างสรรค์เพิ่มเติม', ''), 4, 1);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('Good', ''), NULLIF('(3) - การจัดการวัตถุดิบ: จัดการวัตถุดิบได้ในระดับพื้นฐาน มีข้อผิดพลาดบางประการในด้านคุณภาพหรือการควบคุมต้นทุน - การเตรียมและประกอบอาหาร: ดำเนินการได้ในระดับพื้นฐาน แต่ยังขาดความคล่องตัวและความละเอียดในกระบวนการ - การบริหารจัดการ: จัดการงานในครัวได้ในระดับทั่วไป มีการวางแผนแต่ยังไม่ครอบคลุมทุกมิติของการดำเนินงาน - การประยุกต์องค์ความรู้: ประยุกต์ใช้ความรู้ได้ในระดับพื้นฐาน แต่ยังไม่สามารถแก้ปัญหาหรือพัฒนาแนวทางใหม่ๆ ได้อย่างมีประสิทธิภาพ', ''), 3, 2);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', NULLIF('Fair', ''), NULLIF('(2) - การจัดการวัตถุดิบ: มีข้อผิดพลาดในการจัดการวัตถุดิบบ่อยครั้ง ไม่สามารถควบคุมคุณภาพและต้นทุนได้อย่างมีประสิทธิภาพ - การเตรียมและประกอบอาหาร: ขาดความแม่นยำในกระบวนการเตรียมและประกอบอาหาร ส่งผลต่อคุณภาพของผลิตภัณฑ์ - การบริหารจัดการ: จัดการงานในครัวได้อย่างไม่เพียงพอ มีปัญหาในด้านการวางแผนและการจัดลำดับความสำคัญ - การประยุกต์องค์ความรู้: ขาดทักษะในการประยุกต์ใช้ความรู้เพื่อแก้ปัญหาและพัฒนาธุรกิจ', ''), 2, 3);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('Needs Improvement', ''), NULLIF('(1) - การจัดการวัตถุดิบ: ไม่สามารถจัดการวัตถุดิบได้อย่างเหมาะสม ส่งผลให้เกิดความสูญเสียทั้งคุณภาพและต้นทุน - การเตรียมและประกอบอาหาร: กระบวนการเตรียมและประกอบอาหารมีปัญหาอย่างรุนแรง ไม่เป็นไปตามมาตรฐาน - การบริหารจัดการ: ขาดความสามารถในการจัดการงานในครัว ส่งผลต่อประสิทธิภาพการทำงานโดยรวม - การประยุกต์องค์ความรู้: ไม่สามารถประยุกต์ใช้ความรู้ในสถานการณ์จริง หรือพัฒนาธรุ กิจได้อย่างเหมาะสม ผลลัพธ์การเรียนรู้ที่คาดหวัง ระดับ ตัวชี้วัด (Indicators) (2)', ''), 1, 4);
  -- Section: ด้านทักษะ (Skills)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านทักษะ (Skills)', NULLIF('', ''), 'skills'::domain_type, 2)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': สามารถสื่อสารภาษาไทยและ ยอดเยี่ยม (5) - ฟัง: เข้าใจข้อมูลและแนวคิดที่ซับซ้อนทั้งภาษาไทยและภาษาอังกฤษ และสามารถสรุปประเด็นสำคัญได้อย่างถูกต้อง - พูด: สื่อสารด้วยภาษาไทยและภาษาอังกฤษได้อย่างมั่นใจ ชัดเจน มีความคล่องตัว และใช้คำศัพท์ที่เหมาะสมในบริบทการทำงาน ภาษาอังกฤษ เพื่อใช้ในการทำงาน ด้าน - อ่าน: วิเคราะห์และตีความเอกสารหรือข้อมูลที่เกี่ยวข้องได้อย่างถูกต้องและรวดเร็วทั้งสองภาษา อุตสาหกรรมบริการอาหาร ทั้งการฟัง พูด - เขียน: เขียนรายงาน บันทึก หรืออีเมลทางธุรกิจได้อย่างมืออาชีพในทั้งสองภาษา - เสนอผลงาน: นำเสนอแนวคิดหรือผลงานในบริบทที่เป็นทางการได้อย่างโดดเด่น ใช้สื่อช่วยในการนำเสนออย่างมีประสิทธิภาพ อ่าน เขียน และเสนอผลงานได้ตาม', NULLIF('', ''), NULLIF('LO2', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('Very Good', ''), NULLIF('(4) - ฟัง: เข้าใจข้อมูลและแนวคิดที่ซับซ้อนพอสมควรในภาษาไทยและภาษาอังกฤษ พร้อมสรุปเนื้อหาได้อย่างถูกต้องในระดับดี วัตถุประสงค์ - พูด: สื่อสารภาษาไทยและภาษาอังกฤษได้ดี มีความมั่นใจ แต่ยังมีข้อผิดพลาดเล็กน้อยในด้านโครงสร้างหรือคำศัพท์ - อ่าน: เข้าใจเอกสารหรือข้อมูลในระดับดี และสามารถสรุปประเด็นสำคัญได้อย่างถูกต้อง - เขียน: เขียนข้อความหรือเอกสารทางธุรกิจได้ดี แต่ยังมีข้อผิดพลาดเล็กน้อย - เสนอผลงาน: นำเสนอผลงานในบริบทที่เป็นทางการได้ดี มีการใช้สื่อช่วยที่เหมาะสม', ''), 4, 1);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('Good', ''), NULLIF('(3) - ฟัง: เข้าใจข้อมูลในระดับพื้นฐานถึงปานกลางในทั้งสองภาษา แต่ยังมีข้อจำกัดในการเขา้ ใจเนื้อหาที่ซับซ้อน - พูด: สื่อสารภาษาไทยและภาษาอังกฤษได้ในระดับใช้งานทั่วไป แต่ยังขาดความคล่องแคล่วและความมั่นใจในบางสถานการณ์ - อ่าน: อ่านและเข้าใจเอกสารทั่วไปได้ แต่ยังต้องการเวลามากขึ้นในเนื้อหาที่ซับซ้อน - เขียน: เขียนเอกสารทางธุรกิจได้ในระดับพื้นฐาน มีข้อผิดพลาดในด้านโครงสร้างหรือคำศัพท์ - เสนอผลงาน: นำเสนอผลงานได้ในระดับทั่วไป แต่ยังขาดการจัดโครงสร้างที่ชัดเจนหรือความมั่นใจในบางจุด', ''), 3, 2);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', NULLIF('Fair', ''), NULLIF('(2) - ฟัง: เข้าใจเฉพาะข้อมูลพื้นฐานในภาษาไทยและภาษาอังกฤษ อาจต้องฟังซ้ำหรือขอคำอธิบายเพิ่มเติม - พูด: สื่อสารภาษาไทยและภาษาอังกฤษในระดับพื้นฐานได้ แต่ยังมีข้อผิดพลาดมากในโครงสร้างหรือคำศัพท์ - อ่าน: อ่านและเข้าใจข้อมูลพื้นฐานได้ แต่มีข้อจำกัดมากในเนื้อหาที่ซับซ้อน - เขียน: เขียนข้อความง่าย ๆ ได้ แต่ยังมีปัญหาด้านการจัดโครงสร้างและการใช้คำ - เสนอผลงาน: นำเสนอผลงานได้เพียงบางส่วน มีความไม่ชัดเจนและขาดการเตรียมตัว', ''), 2, 3);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('Needs Improvement', ''), NULLIF('(1) - ฟัง: ไม่สามารถเข้าใจข้อมูลที่ได้รับทั้งภาษาไทยและภาษาอังกฤษได้ในระดับที่เพียงพอ - พูด: มีข้อจำกัดอย่างมากในการสื่อสาร อาจไม่สามารถสื่อสารความคิดหรือข้อมูลได้อย่างมีประสิทธิภาพ - อ่าน: ไม่สามารถอ่านหรือเข้าใจข้อมูลพื้นฐานได้ในทั้งสองภาษา - เขียน: เขียนข้อความที่มีความผิดพลาดมาก และไม่สามารถสื่อสารความคิดได้อย่างชัดเจน - เสนอผลงาน: ไม่สามารถนำเสนอผลงานได้อย่างชัดเจน และไมม่ ีการใช้สื่อช่วยในการนำเสนอ ผลลัพธ์การเรียนรู้ที่คาดหวัง ระดับ ตัวชี้วัด (Indicators)', ''), 1, 4);
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': สามารถประยุกต์ใช้เทคโนโลยี ยอดเยี่ยม (5) - การใช้เทคโนโลยี: ใช้เทคโนโลยีสารสนเทศขั้นสูงเพื่อสืบค้น วิเคราะห์ และนำเสนอข้อมูลได้อย่างมีประสิทธิภาพสูงสุด พร้อมพัฒนาวิธีการใหม่ๆ เพื่อเพิ่มประสิทธิภาพในการทำงาน สารสนเทศเพื่อสืบค้นข้อมูล วิเคราะห์ - การวิเคราะห์ข้อมูล: วิเคราะห์ข้อมูลได้ลึกซึ้ง ครอบคลุม และมีความแม่นยำสูง โดยเชื่อมโยงกับสถานการณ์ปัจจุบัน ข้อมูล นำเสนอข้อมูล และสามารถปรับตัว - การนำเสนอข้อมูล: นำเสนอข้อมูลได้อย่างสร้างสรรค์ ชัดเจน ใช้เครื่องมือและสื่อที่ทันสมัยในการสื่อสารได้อย่างมืออาชีพ ในสถานการณ์ที่มีการเปลี่ยนแปลงในด้าน - การปรับตัว: สามารถปรับตัวได้อย่างรวดเร็วและมีประสิทธิภาพในสถานการณ์เปลี่ยนแปลง ทั้งด้านสังคม วัฒนธรรม เศรษฐกิจ และสิ่งแวดล้อม พร้อมให้ข้อเสนอแนะที่เป็นประโยชน์ต่อทีมงานหรือองค์กร สังคมวัฒนธรรม เศรษฐกิจและสิ่งแวดล้อม', NULLIF('', ''), NULLIF('LO3', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('Very Good', ''), NULLIF('(4) - การใช้เทคโนโลยี: ใช้เทคโนโลยีสารสนเทศได้ดีในการสืบค้น วิเคราะห์ และนำเสนอข้อมูล แต่ยังไม่หลากหลายหรือซับซ้อนมากนัก มีความพร้อมในการปฏิบัติงานใน - การวิเคราะห์ข้อมูล: วิเคราะห์ข้อมูลได้อย่างถูกต้องและครอบคลุม แต่ยังมีข้อจำกัดในบางมิติ อุตสาหกรรมบริการอาหารได้อย่าง - การนำเสนอข้อมูล: นำเสนอข้อมูลได้อย่างชัดเจน ใช้เครื่องมือที่เหมาะสม แต่ยังมีโอกาสในการปรับปรุงความน่าสนใจหรือความลื่นไหล - การปรับตัว: ปรับตัวได้ดีในสถานการณ์เปลี่ยนแปลง มีการประยุกต์ความรู้และทักษะได้เหมาะสมในระดับดี เหมาะสมตามสถานการณ์', ''), 4, 1);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('Good', ''), NULLIF('(3) - การใช้เทคโนโลยี: ใช้เทคโนโลยีสารสนเทศได้ในระดับพื้นฐาน สามารถสืบค้น วิเคราะห์ และนำเสนอข้อมูลได้ในกรอบที่กำหนด - การวิเคราะห์ข้อมูล: วิเคราะห์ข้อมูลได้ในระดับทั่วไป อาจขาดความลึกซึ้งหรือการเชื่อมโยงเชิงกลยุทธ์ - การนำเสนอข้อมูล: นำเสนอข้อมูลได้ในระดับทั่วไป มีความชัดเจนในบางส่วน แต่ยังขาดการใช้เทคโนโลยีหรือเครื่องมือช่วยที่เหมาะสม - การปรับตัว: ปรับตัวได้ในระดับพื้นฐาน มีความยืดหยุ่นในสถานการณ์เปลี่ยนแปลง แต่ยังต้องการคำแนะนำหรือการสนับสนุนเพิ่มเติม', ''), 3, 2);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', NULLIF('Fair', ''), NULLIF('(2) - การใช้เทคโนโลยี: ใช้เทคโนโลยีสารสนเทศได้อย่างจำกัด มีข้อผิดพลาดในการสืบค้น วิเคราะห์ หรือการนำเสนอข้อมูล - การวิเคราะห์ข้อมูล: วิเคราะห์ข้อมูลได้อย่างผิวเผิน และไม่สามารถเชื่อมโยงกับบริบทได้อย่างเหมาะสม - การนำเสนอข้อมูล: การนำเสนอข้อมูลขาดความชัดเจน ใช้เครื่องมือหรือเทคโนโลยีได้ไม่เหมาะสม - การปรับตัว: ปรับตัวในสถานการณ์เปลี่ยนแปลงได้ช้า ต้องการการสนับสนุนจากผู้อื่นอย่างมาก', ''), 2, 3);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('Needs Improvement', ''), NULLIF('(1) - การใช้เทคโนโลยี: ไม่สามารถใช้เทคโนโลยีสารสนเทศได้อย่างเหมาะสม มีปัญหาในการสืบค้น วิเคราะห์ และนำเสนอข้อมูล - การวิเคราะห์ข้อมูล: ขาดทักษะในการวิเคราะห์ข้อมูลอย่างชัดเจนและถูกต้อง - การนำเสนอข้อมูล: นำเสนอข้อมูลได้ไม่ชัดเจน มีปัญหาด้านการจัดการข้อมูลและการสื่อสาร - การปรับตัว: ไม่สามารถปรับตัวในสถานการณ์เปลี่ยนแปลงได้ ต้องการการสนับสนุนและคำแนะนำอย่างมาก ผลลัพธ์การเรียนรู้ที่คาดหวัง ระดับ ตัวชี้วัด (Indicators)', ''), 1, 4);
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': สามารถประกอบอาหารอย่าง ยอดเยี่ยม (5) - เทคนิคการประกอบอาหาร: ดำเนินการประกอบอาหารโดยใช้ความร้อนชื้น ความร้อนแห้ง และความร้อนผสมผสานได้อย่างถูกต้องและแม่นยำ ตามประเภทของอาหาร พร้อมปรับแต่งเทคนิคให้เหมาะสมกับลักษณะอาหาร ถูกต้องและเหมาะสมกับรายการอาหาร - คุณภาพของอาหาร: ผลลัพธ์ของอาหารมีคุณภาพยอดเยี่ยมทั้งในด้านรสชาติ เนื้อสัมผัส การนำเสนอ และความสม่ำเสมอ ด้วยเทคนิคการประกอบอาหารโดย ใช้ - สุขลักษณะ: ปฏิบัติตามสุขลักษณะของสถานที่จำหน่ายอาหารตามกฎกระทรวง พ.ศ. 2561 ได้อย่างครบถ้วน มีการจัดการพื้นที่ทำงานและ ความร้อนชื้น ใช้ความร้อนแห้ง และใช้ อุปกรณ์ได้สะอาด ปลอดภัย - การบริหารเวลา: สามารถบริหารเวลาได้ดีเยี่ยม และส่งมอบอาหารทันเวลาในทุกสถานการณ ์ ความร้อนผสมผสาน (Moist-heat', NULLIF('', ''), NULLIF('LO4', ''), 'single_choice'::question_type, true, 3)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('Very Good', ''), NULLIF('(4) - เทคนิคการประกอบอาหาร: ใช้เทคนิคการประกอบอาหารตามประเภทของความร้อนได้อย่างถูกต้อง ส่วนใหญ่มีความแม่นยำ แต่ยังมี cooking methods, dry-heat cooking ข้อผิดพลาดเล็กน้อยในบางขั้นตอน methods, and combination cooking - คุณภาพของอาหาร: อาหารที่ได้มีคุณภาพดี มีรสชาติและเนื้อสัมผัสที่เหมาะสม แต่ยังมีโอกาสปรับปรุงในด้านการนำเสนอ - สุขลักษณะ: ปฏิบัติตามข้อกำหนดสุขลักษณะของสถานที่จำหน่ายอาหารได้ดี แต่ยังมีบางจุดที่สามารถปรับปรุงให้ดีขึ้น methods) ตามกฎกระทรวงสาธารณสุข - การบริหารเวลา: สามารถส่งมอบอาหารได้ทันเวลา ส่วนใหญ่จัดการเวลาได้ดี แต่บางครั้งอาจล่าช้าเล็กน้อย สุขลักษณะของสถานที่จำหน่ายอาหาร', ''), 4, 1);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('Good', ''), NULLIF('(3) - เทคนิคการประกอบอาหาร: ใช้เทคนิคการประกอบอาหารได้ในระดับพื้นฐาน มีข้อผิดพลาดบางส่วนที่อาจส่งผลต่อคุณภาพของอาหาร พ.ศ. 2561 - คุณภาพของอาหาร: อาหารมีคุณภาพระดับทั่วไป รสชาติ เนื้อสัมผัส และการนำเสนอสามารถปรับปรุงได้ - สุขลักษณะ: ปฏิบัติตามข้อกำหนดด้านสุขลักษณะในระดับพื้นฐาน แต่ยังมีจุดที่ขาดความครบถ้วน เช่น การจัดการความสะอาดอุปกรณ์ - การบริหารเวลา: มีปัญหาในการบริหารเวลาในบางกรณี ส่งผลให้การประกอบอาหารไม่ทันเวลา', ''), 3, 2);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', NULLIF('Fair', ''), NULLIF('(2) - เทคนิคการประกอบอาหาร: ใช้เทคนิคการประกอบอาหารได้อย่างจำกัด มีข้อผิดพลาดที่ส่งผลกระทบต่อผลลัพธ์ของอาหาร - คุณภาพของอาหาร: คุณภาพของอาหารไม่เป็นไปตามมาตรฐาน รสชาติและเนื้อสัมผัสไม่สมำ่ เสมอ - สุขลักษณะ: มีการละเลยข้อกำหนดด้านสุขลักษณะในบางส่วน เช่น พื้นที่ทำงานไม่สะอาดเพียงพอ - การบริหารเวลา: ไม่สามารถจัดการเวลาได้อย่างเหมาะสม ส่งผลให้การส่งมอบอาหารล่าชา้ หรือไม่เสร็จทันกำหนด', ''), 2, 3);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('Needs Improvement', ''), NULLIF('(1) - เทคนิคการประกอบอาหาร: ไม่สามารถใช้เทคนิคการประกอบอาหารได้อย่างถูกต้อง อาหารที่ได้ไม่เป็นไปตามประเภทหรือมาตรฐานที่กำหนด - คุณภาพของอาหาร: อาหารมีคุณภาพต่ำ รสชาติ เนื้อสัมผัส และการนำเสนอไม่เหมาะสม - สุขลักษณะ: ไม่ปฏิบัติตามกฎกระทรวงสาธารณสุขในด้านสุขลักษณะอย่างรุนแรง มีปัญหาในเรื่องความสะอาดและความปลอดภัยของพื้นที่ - การบริหารเวลา: ล้มเหลวในการบริหารเวลา ทำให้งานไม่เสร็จสิ้นหรือไมม่ ีคุณภาพ ผลลัพธ์การเรียนรู้ที่คาดหวัง ระดับ ตัวชี้วัด (Indicators)', ''), 1, 4);
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': สามารถออกแบบรายการอาหารแต่ ยอดเยี่ยม (5) - ความสร้างสรรค์: ออกแบบรายการอาหารที่มีความแปลกใหม่ สร้างสรรค์ มีเอกลักษณ์เฉพาะตัว และตอบโจทย์ความต้องการของผู้บริโภคใน กลุ่มเป้าหมาย ละประเภทอย่างสร้างสรรค์ถูกต้องและ - ความถูกต้อง: วางแผนและจัดการเมนูอาหารได้อย่างถูกต้องทั้งในแง่โภชนาการ วัตถุดิบ และเทคนิคการปรุง เหมาะสมกับผู้บริโภค - ความเหมาะสม: รายการอาหารที่ออกแบบเหมาะสมกับกลุ่มผู้บริโภค ทั้งด้านรสชาติ วัฒนธรรม และงบประมาณ - การนำเสนอ: สามารถนำเสนอแนวคิดและอธิบายรายการอาหารได้อย่างมืออาชีพ ใช้สื่อประกอบการนำเสนอได้อย่างมีประสิทธิภาพและ น่าสนใจ', NULLIF('', ''), NULLIF('LO5', ''), 'single_choice'::question_type, true, 4)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('Very Good', ''), NULLIF('(4) - ความสร้างสรรค์: ออกแบบรายการอาหารที่มีความสรา้ งสรรค์ดี และมีความน่าสนใจ แต่ยังขาดเอกลักษณ์เล็กน้อยในบางจุด - ความถูกต้อง: วางแผนเมนูอาหารได้ถูกต้อง ส่วนใหญ่ตรงตามมาตรฐานโภชนาการและการปรุงอาหาร - ความเหมาะสม: รายการอาหารเหมาะสมกับกลุ่มผู้บริโภค แต่ยังมีบางจุดที่ต้องปรับให้ตอบสนองความต้องการได้ดีขึ้น - การนำเสนอ: นำเสนอแนวคิดได้ดี มีความชัดเจน แต่ยังสามารถพัฒนาความนา่ สนใจของสื่อหรือวิธีการนำเสนอเพิ่มเติมได ้', ''), 4, 1);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('Good', ''), NULLIF('(3) - ความสร้างสรรค์: ออกแบบรายการอาหารได้ในระดับทั่วไป มีแนวคิดสร้างสรรค์บางส่วน แต่ยังขาดความโดดเด่น - ความถูกต้อง: วางแผนเมนูได้ในระดับพื้นฐาน มีข้อผิดพลาดบางประการในด้านโภชนาการหรือเทคนิคการปรุง - ความเหมาะสม: รายการอาหารเหมาะสมในระดับทั่วไป แต่ยังไม่ตอบโจทย์ความต้องการเฉพาะของกลุ่มผู้บริโภค - การนำเสนอ: นำเสนอแนวคิดได้ในระดับทั่วไป มีความชัดเจนบางส่วน แต่ยังขาดความน่าสนใจหรือความชัดเจนในรายละเอียด', ''), 3, 2);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', NULLIF('Fair', ''), NULLIF('(2) - ความสร้างสรรค์: การออกแบบรายการอาหารมีความธรรมดาและขาดความนา่ สนใจ - ความถูกต้อง: วางแผนเมนูอาหารได้ในระดับที่จำกัด มีข้อผิดพลาดสำคัญในด้านโภชนาการหรือการปรุงอาหาร - ความเหมาะสม: รายการอาหารไม่เหมาะสมกับกลุ่มผู้บริโภค เช่น ขาดความเข้ากับวัฒนธรรมหรืองบประมาณ - การนำเสนอ: นำเสนอแนวคิดได้ในระดับพอใช้ ขาดความชัดเจน และไม่มีการใช้สื่อช่วยในการนำเสนออย่างเหมาะสม', ''), 2, 3);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('Needs Improvement', ''), NULLIF('(1) - ความสร้างสรรค์: ไม่สามารถออกแบบรายการอาหารที่มีความสรา้ งสรรค์หรือโดดเด่นได้ - ความถูกต้อง: การวางแผนเมนูมีปัญหาร้ายแรงในด้านความถูกต้อง เช่น ไม่เหมาะสมกับหลักโภชนาการหรือการใช้วัตถุดิบ - ความเหมาะสม: รายการอาหารไม่เหมาะสมกับกลุ่มผู้บริโภคในด้านรสชาติ วัฒนธรรม หรือข้อจำกัดทางงบประมาณ - การนำเสนอ: ไม่สามารถนำเสนอแนวคิดหรืออธิบายรายละเอียดของรายการอาหารได้อย่างชัดเจน ผลลัพธ์การเรียนรู้ที่คาดหวัง ระดับ ตัวชี้วัด (Indicators)', ''), 1, 4);
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': สามารถวางแผนการดำเนินงาน คิด ยอดเยี่ยม (5) - การวางแผนการดำเนินงาน: วางแผนการดำเนินงานได้อย่างละเอียด รอบคอบ และครอบคลุมทุกแง่มุมของงานด้านอุตสาหกรรมบริการอาหาร พร้อมทั้งจัดลำดับความสำคัญของงานได้อย่างเหมาะสม วิเคราะห์ การจัดการบริหารจัดการ และ - การคิดวิเคราะห์: วิเคราะห์สถานการณ์และข้อมูลได้อย่างลึกซึ้ง เชื่อมโยงปัจจัยต่างๆ ได้ครบถ้วน พร้อมนำเสนอแนวทางการปรับปรุงหรือ การแก้ไขปัญหาในการปฏิบัติงานด้าน พัฒนาที่สร้างสรรค ์ อุตสาหกรรมบริการอาหารได้อย่าง - การจัดการ: จัดการทรัพยากร บุคลากร และเวลาได้อย่างมีประสิทธิภาพ พร้อมทั้งใช้เทคโนโลยีหรือเครื่องมือที่ทันสมัย - การแก้ไขปัญหา: สามารถระบุปัญหาได้อย่างรวดเร็วและแก้ไขปัญหาได้อย่างเหมาะสมและมีประสิทธิภาพ พร้อมทั้งให้คำแนะนำหรือแนว เหมาะสมตามสถานการณ์ ทางแก้ไขในเชิงป้องกัน', NULLIF('', ''), NULLIF('LO6', ''), 'single_choice'::question_type, true, 5)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('Very Good', ''), NULLIF('(4) - การวางแผนการดำเนินงาน: วางแผนการดำเนินงานได้ดี มีความรอบคอบในระดับสูง แต่ยังมีบางจุดที่ขาดรายละเอียดเพิ่มเติม - การคิดวิเคราะห์: วิเคราะห์สถานการณ์และข้อมูลได้ในระดับดี ส่วนใหญ่สามารถเชื่อมโยงปัจจัยต่างๆ ได้ครบถ้วน - การจัดการ: จัดการทรัพยากร บุคลากร และเวลาได้อย่างเหมาะสม แต่ยังมีโอกาสพัฒนาความคล่องตัวหรือการใช้เทคโนโลยี - การแก้ไขปัญหา: ระบุปัญหาและแก้ไขได้ดีในระดับส่วนใหญ่ แต่ยังมีบางสถานการณ์ที่การแก้ปัญหาขาดความรวดเร็วหรือเชิงลึก', ''), 4, 1);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('Good', ''), NULLIF('(3) - การวางแผนการดำเนินงาน: วางแผนการดำเนินงานได้ในระดับทั่วไป มีข้อผิดพลาดหรือขาดรายละเอียดในบางส่วนที่สำคัญ - การคิดวิเคราะห์: วิเคราะห์สถานการณ์ได้ในระดับพื้นฐาน ขาดความลึกซึ้งหรือการเชื่อมโยงปัจจัยต่างๆ - การจัดการ: จัดการทรัพยากรได้ในระดับทั่วไป มีข้อจำกัดในการใช้เวลาและบุคลากร - การแก้ไขปัญหา: สามารถระบุและแก้ไขปัญหาได้ในระดับพื้นฐาน แต่ยังขาดความชัดเจนหรือวิธีการที่เหมาะสมในบางกรณี', ''), 3, 2);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', NULLIF('Fair', ''), NULLIF('(2) - การวางแผนการดำเนินงาน: วางแผนการดำเนินงานได้อย่างไม่รอบคอบ ขาดการจัดลำดับความสำคัญและรายละเอียดที่สำคัญ - การคิดวิเคราะห์: วิเคราะห์สถานการณ์ได้อย่างจำกัด ไม่สามารถเชื่อมโยงปัจจัยที่เกี่ยวข้องได้เพียงพอ - การจัดการ: มีปัญหาในการจัดการทรัพยากร บุคลากร และเวลา ทำให้งานไม่เป็นไปตามเป้าหมายที่วางไว้ - การแก้ไขปัญหา: ไม่สามารถระบุหรือแก้ไขปัญหาได้อย่างเหมาะสม ต้องพึ่งพาผู้อื่นในการแก้ไข', ''), 2, 3);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('Needs Improvement', ''), NULLIF('(1) - การวางแผนการดำเนินงาน: ไม่สามารถวางแผนการดำเนินงานได้อย่างเหมาะสม ขาดการจัดการและลำดับความสำคัญ - การคิดวิเคราะห์: ไม่สามารถวิเคราะห์สถานการณ์หรือข้อมูลที่ได้รับได้อย่างมีประสิทธิภาพ - การจัดการ: ล้มเหลวในการจัดการทรัพยากร บุคลากร และเวลา ทำให้งานล่าช้าหรือไม่สำเร็จ - การแก้ไขปัญหา: ไม่สามารถระบุปัญหาและแก้ไขได้อย่างเหมาะสม ส่งผลให้สถานการณ์แย่ลงหรือไม่สามารถแก้ไขได้ ผลลัพธ์การเรียนรู้ที่คาดหวัง ระดับ ตัวชี้วัด (Indicators) (3)', ''), 1, 4);
