  VALUES (t_id, s_id, ': ประยุกต์ความรู้ด้านบริหารธุรกิจและการจัดการนวัตกรรมเพื่อการดำเนินงานด้านการท่องเที่ยวและการโรงแรม', NULLIF('', ''), NULLIF('LO1', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ประยุกต์ความรู้การจัดการการท่องเที่ยวและการโรงแรมเพื่อการปฏิบัติงานด้านการท่องเที่ยวและการโรงแรม', NULLIF('', ''), NULLIF('LO2', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  -- Section: ด้านทักษะ (Skills)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านทักษะ (Skills)', NULLIF('', ''), 'skills'::domain_type, 2)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีทักษะการสื่อสารภาษาไทย และภาษาอังกฤษ เพื่อใช้ในชีวิตประจำวันและในการทำงานด้านการท่องเที่ยวและการโรงแรมทั้งการฟัง พูด อ่าน เขียน และนำเสนอผลงานได้อย่างเหมาะสมกับ สถานการณ์ ในกรณีนักศึกษาเลือกภาษาจีน สามารถสื่อสารภาษาจีน ในชีวิตประจำวันได้', NULLIF('', ''), NULLIF('LO3', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
