  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': แสดงออกถึงการมีวินัย มีภาวะผู้นำ สามารถเป็นได้ทั้งผู้นำ และผู้ตาม ทำงานร่วมกับผู้อื่นได้ มีจิตอาสา และสามารถพัฒนาตนเองในงานด้านการท่องเที่ยวและการโรงแรมได้อย่างต่อเนื่อง ผลการเรียนรู้ที่คาดหวัง | ผลการประเมิน (1)', NULLIF('', ''), NULLIF('LO12', ''), 'single_choice'::question_type, true, 2)
