  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ประยุกต์ความรู้ด้านบริหารธุรกิจและการจัดการนวัตกรรมเพื่อการดำเนินงานด้านการท่องเที่ยวและการโรงแรม |   5 (ยอดเยี่ยม): นักศึกษาสามารถวิเคราะห์สถานการณ์และเสนอแนวทางแก้ไขปัญหาโดยใช้หลักการบริหารธุรกิจได้อย่างเป็นระบบ นำเสนอนวัตกรรมหรือแนวคิดใหม่ๆ ที่สามารถนำไปใช้ได้จริงในองค์กร มีการบูรณาการความรู้จากหลายศาสตร์มาประยุกต์ใช้ได้อย่างเหมาะสม   4 (ดีมาก): นักศึกษาสามารถประยุกต์ใช้หลักการบริหารธุรกิจในการทำงานได้ดี มีการนำเสนอแนวคิดใหม่ๆ ในการพัฒนางาน เข้าใจและเชื่อมโยงทฤษฎีสู่การปฏิบัติได้   3 (ดี): นักศึกษาเข้าใจหลักการบริหารธุรกิจพื้นฐานและนำมาใช้ในงานได้ ทำงานตามกระบวนการมาตรฐานขององค์กรได้ดี รู้จักปรับปรุงวิธีการทำงานเมื่อได้รับคำแนะนำ   2 (พอใช้): นักศึกษาเข้าใจหลักการพื้นฐานแต่ประยุกต์ใช้ได้จำกัด ต้องได้รับคำแนะนำในการทำงานบ่อยครั้ง ทำงานตามที่ได้รับมอบหมายได้แต่ขาดการริเริ่ม   1 (ต้องปรับปรุง): นักศึกษาไม่สามารถนำความรู้มาประยุกต์ใช้ในงานได้ ไม่เข้าใจหลักการพื้นฐานที่จำเป็น ต้องได้รับการกำกับดูแลอย่างใกล้ชิดตลอดเวลา', NULLIF('', ''), NULLIF('LO1', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ประยุกต์ความรู้การจัดการการท่องเที่ยวและการโรงแรมเพื่อการปฏิบัติงานด้านการท่องเที่ยวและการโรงแรม |   5 (ยอดเยี่ยม): นักศึกษาสามารถจัดการงานบริการได้อย่างมีประสิทธิภาพสูง โดยได้รับความพึงพอใจจากลูกค้า > 90% แก้ไขสถานการณ์เฉพาะหน้าได้อย่างเหมาะสมและรวดเร็ว สามารถสอนงานหรือแนะนำเพื่อนร่วมงานได้   4 (ดีมาก): นักศึกษาสามารถจัดการงานบริการได้ดี ได้รับความพึงพอใจจากลูกค้า 80-90% แก้ไขปัญหาพื้นฐานในงานบริการได้ด้วยตนเอง มีการวางแผนและจัดลำดับความสำคัญของงานได้ดี   3 (ดี): นักศึกษาสามารถให้บริการตามมาตรฐานได้ดี ได้รับความพึงพอใจจากลูกค้า 70-79% ทำงานตามขั้นตอนที่กำหนดได้ครบถ้วน สื่อสารกับลูกค้าและเพื่อนร่วมงานได้อย่างเหมาะสม   2 (พอใช้): นักศึกษาสามารถให้บริการได้ตามมาตรฐานขั้นต่ำ ได้รับความพึงพอใจจากลูกค้า 60-69% ต้องได้รับคำแนะนำในการแก้ไขปัญหาเสมอ การสื่อสารกับลูกค้ายังมีข้อบกพร่อง   1 (ต้องปรับปรุง): ไม่สามารถให้บริการตามมาตรฐานขั้นต่ำ ได้รับความพึงพอใจจากลูกค้า < 60% ไม่สามารถแก้ไขปัญหาพื้นฐานได้ มีปัญหาในการสื่อสารกับลูกค้าและเพื่อนร่วมงาน (2)', NULLIF('', ''), NULLIF('LO2', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  -- Section: ด้านทักษะ (Skills)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านทักษะ (Skills)', NULLIF('', ''), 'skills'::domain_type, 6)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีทักษะการสื่อสารภาษาไทย และภาษาอังกฤษ เพื่อใช้ในชีวิตประจำวันและในการทำงานด้านการท่องเที่ยวและการโรงแรมทั้งการฟัง พูด อ่าน เขียน และนำเสนอผลงานได้อย่างเหมาะสมกับ สถานการณ์ ในกรณีนักศึกษาเลือกภาษาจีน สามารถสื่อสารภาษาจีน ในชีวิตประจำวันได้ |   5 (ยอดเยี่ยม): นักศึกษาสามารถสื่อสารภาษาไทยและภาษาอังกฤษได้อย่างคล่องแคล่วทั้งการฟัง พูด อ่าน เขียน สามารถนำเสนองานเป็นภาษาอังกฤษได้อย่างมีประสิทธิภาพ กรณีเลือกภาษาจีน: สื่อสารในชีวิตประจำวันและงานบริการได้อย่างคล่องแคล่ว   4 (ดีมาก): นักศึกษาสามารถสื่อสารภาษาไทยได้ดีมาก และภาษาอังกฤษได้ดี นำเสนองานเป็นภาษาอังกฤษได้ โดยมีข้อผิดพลาดเล็กน้อย กรณีเลือกภาษาจีน: สื่อสารในชีวิตประจำวันได้ดี มีข้อผิดพลาดน้อย   3 (ดี): นักศึกษาสามารถสื่อสารภาษาไทยได้ดี และภาษาอังกฤษได้ในระดับใช้งาน นำเสนองานเป็นภาษาอังกฤษได้ แต่ต้องเตรียมตัวมาก กรณีเลือกภาษาจีน: สื่อสารประโยคพื้นฐานในชีวิตประจำวันได้   2 (พอใช้): นักศึกษาสามารถสื่อสารภาษาไทยได้พอใช้ ภาษาอังกฤษมีข้อจำกัด ต้องได้รับความช่วยเหลือในการนำเสนองานภาษาอังกฤษ กรณีเลือกภาษาจีน: สื่อสารได้เฉพาะประโยคง่ายๆ   1 (ต้องปรับปรุง): นักศึกษามีปัญหาในการสื่อสารทั้งภาษาไทยและภาษาอังกฤษ ไม่สามารถนำเสนองานเป็นภาษาอังกฤษได้ กรณีเลือกภาษาจีน: ไม่สามารถสื่อสารภาษาจีนได้แม้แต่ประโยคพื้นฐาน', NULLIF('', ''), NULLIF('LO3', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีทักษะการใช้เทคโนโลยีสารสนเทศเพื่อสืบค้นข้อมูล วิเคราะห์ นำเสนอ และมีทักษะการใช้โปรแกรมประยุกต์ในงานด้านการท่องเที่ยวและการโรงแรม |   5 (ยอดเยี่ยม): นักศึกษาสามารถใช้โปรแกรมสำนักงานและระบบสารสนเทศขององค์กรได้อย่างคล่องแคล่ว สามารถแก้ไขปัญหาทางเทคนิคเบื้องต้นได้ด้วยตนเอง สามารถประยุกต์ใช้เทคโนโลยีใหม่ๆ เพื่อพัฒนางานได้   4 (ดีมาก): นักศึกษาสามารถใช้โปรแกรมสำนักงานได้ดี และเรียนรู้ระบบใหม่ได้เร็ว ต้องการความช่วยเหลือในการแก้ปัญหาทางเทคนิคเพียงเล็กน้อย มีความคิดริเริ่มในการใช้เทคโนโลยีเพื่อพัฒนางาน   3 (ดี): นักศึกษาสามารถใช้โปรแกรมพื้นฐานได้ดี เรียนรู้ระบบใหม่ได้เมื่อได้รับการสอน ทำงานกับระบบสารสนเทศขององค์กรได้ตามมาตรฐาน   2 (พอใช้): นักศึกษาสามารถใช้โปรแกรมพื้นฐานได้แต่มีข้อจำกัด ต้องการความช่วยเหลือในการใช้ระบบใหม่บ่อยครั้ง ทำงานกับระบบสารสนเทศได้ช้า   1 (ต้องปรับปรุง): นักศึกษาไม่สามารถใช้โปรแกรมพื้นฐานได้อย่างมีประสิทธิภาพ ไม่สามารถเรียนรู้ระบบใหม่ได้แม้จะได้รับการสอน มีปัญหาในการใช้ระบบสารสนเทศขององค์กร', NULLIF('', ''), NULLIF('LO4', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีทักษะการแก้ไขปัญหาในการปฏิบัติงานด้านการท่องเที่ยวและการโรงแรม โดยการคิดวิเคราะห์ อย่างมีเหตุผล |   5 (ยอดเยี่ยม): นักศึกษาสามารถวิเคราะห์สาเหตุของปัญหาได้อย่างเป็นระบบ เสนอทางเลือกในการแก้ปัญหาได้หลากหลายและสร้างสรรค์ แก้ไขปัญหาเฉพาะหน้าได้อย่างมีประสิทธิภาพ โดยคำนึงถึงผลกระทบระยะยาว   4 (ดีมาก): นักศึกษาสามารถวิเคราะห์ปัญหาได้ดี เสนอแนวทางแก้ไขปัญหาได้มากกว่า 1 แนวทาง แก้ไขปัญหาเฉพาะหน้าได้ดี   3 (ดี): นักศึกษาสามารถระบุปัญหาและสาเหตุได้ เสนอแนวทางแก้ไขปัญหาได้ 1 แนวทาง แก้ไขปัญหาพื้นฐานได้ตามแนวทางที่กำหนด   2 (พอใช้): นักศึกษาสามารถระบุปัญหาได้แต่วิเคราะห์สาเหตุได้ไม่ชัดเจน ต้องได้รับคำแนะนำในการแก้ไขปัญหา แก้ไขปัญหาได้เฉพาะเมื่อมีผู้ชี้แนะ   1 (ต้องปรับปรุง): นักศึกษาไม่สามารถระบุปัญหาและสาเหตุได้ ไม่สามารถเสนอแนวทางแก้ไขปัญหา ไม่สามารถแก้ไขปัญหาได้แม้จะได้รับคำแนะนำ', NULLIF('', ''), NULLIF('LO5', ''), 'single_choice'::question_type, true, 3)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีทักษะการให้บริการและนันทนาการด้านการท่องเที่ยวและการโรงแรมแก่ลูกค้า |   5 (ยอดเยี่ยม): นักศึกษาสามารถให้บริการและหรือจัดกิจกรรมนันทนาการที่สร้างสรรค์และเหมาะสมกับกลุ่มลูกค้าได้โดดเด่น แก้ไขสถานการณ์เฉพาะหน้าในการให้บริการได้อย่างยอดเยี่ยม ได้รับความพึงพอใจจากลูกค้าในระดับดีเยี่ยม (>90%)   4 (ดีมาก): นักศึกษาสามารถให้บริการและหรือจัดกิจกรรมนันทนาการที่น่าสนใจและเหมาะสมกับกลุ่มลูกค้า จัดการสถานการณ์ในการให้บริการได้ดี ได้รับความพึงพอใจจากลูกค้าในระดับดีมาก (80-90%)   3 (ดี): นักศึกษาสามารถให้บริการและหรือจัดกิจกรรมนันทนาการตามแผนที่กำหนดได้ ให้บริการได้ตามมาตรฐาน ได้รับความพึงพอใจจากลูกค้าในระดับดี (70-79%)   2 (พอใช้): นักศึกษาสามารถให้บริการและหรือจัดกิจกรรมนันทนาการได้แต่ต้องมีผู้ช่วยแนะนำ ให้บริการได้แต่ยังมีข้อบกพร่อง ได้รับความพึงพอใจจากลูกค้าในระดับพอใช้ (60-69%)   1 (ต้องปรับปรุง): นักศึกษาไม่สามารถจัดกิจกรรมนันทนาการได้แม้จะมีผู้แนะนำ มีปัญหาในการให้บริการบ่อยครั้ง ได้รับความพึงพอใจจากลูกค้าในระดับต่ำ (<60%)', NULLIF('', ''), NULLIF('LO6', ''), 'single_choice'::question_type, true, 4)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีทักษะการออกแบบประสบการณ์การท่องเที่ยวแก่ลูกค้าในแหล่งท่องเที่ยวและโรงแรม |   5 (ยอดเยี่ยม): นักศึกษาสามารถออกแบบโปรแกรมการท่องเที่ยวที่สร้างสรรค์และตอบโจทย์ความต้องการของลูกค้าได้ดีเยี่ยม บูรณาการทรัพยากรการท่องเที่ยวและบริการต่างๆ ได้อย่างลงตัว นำเสนอประสบการณ์ที่แปลกใหม่และน่าประทับใจ พร้อมคำนึงถึงความยั่งยืน   4 (ดีมาก): นักศึกษาสามารถออกแบบโปรแกรมการท่องเที่ยวที่น่าสนใจและตอบสนองความต้องการของลูกค้าจัดการทรัพยากรการท่องเที่ยวและบริการได้อย่างมีประสิทธิภาพ  สร้างประสบการณ์ที่น่าจดจำให้กับลูกค้าได้   3 (ดี): นักศึกษาสามารถออกแบบโปรแกรมการท่องเที่ยวตามมาตรฐานได้ จัดการทรัพยากรการท่องเที่ยวและบริการได้ตามแผน นำเสนอประสบการณ์ที่เหมาะสมกับกลุ่มลูกค้า   2 (พอใช้): นักศึกษาสามารถออกแบบโปรแกรมการท่องเที่ยวได้แต่ต้องมีผู้แนะนำ จัดการทรัพยากรการท่องเที่ยวและบริการได้แต่มีข้อบกพร่อง นำเสนอประสบการณ์แบบพื้นฐานได้   1 (ต้องปรับปรุง): นักศึกษาไม่สามารถออกแบบโปรแกรมการท่องเที่ยวได้แม้มีผู้แนะนำ มีปัญหาในการจัดการทรัพยากรการท่องเที่ยวและบริการ ไม่สามารถนำเสนอประสบการณ์ที่น่าพอใจให้กับลูกค้า (3)', NULLIF('', ''), NULLIF('LO7', ''), 'single_choice'::question_type, true, 5)
  RETURNING id INTO q_id;
  -- Section: ด้านจริยธรรม (Ethics)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านจริยธรรม (Ethics)', NULLIF('', ''), 'ethics'::domain_type, 7)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ':  มีความรับผิดชอบต่อตนเอง สังคม และสิ่งแวดล้อม |   5 (ยอดเยี่ยม): นักศึกษามีความตรงต่อเวลาและรับผิดชอบงานอย่างสม่ำเสมอ มีส่วนร่วมในกิจกรรมเพื่อสังคมขององค์กรอย่างกระตือรือร้น ริเริ่มและนำเสนอแนวทางการอนุรักษ์สิ่งแวดล้อมในการทำงาน   4 (ดีมาก): นักศึกษามีความตรงต่อเวลาและรับผิดชอบงานเป็นอย่างดี เข้าร่วมกิจกรรมเพื่อสังคมขององค์กรอย่างสม่ำเสมอ ปฏิบัติตามแนวทางการอนุรักษ์สิ่งแวดล้อมขององค์กรอย่างเคร่งครัด   3 (ดี): นักศึกษามีความตรงต่อเวลาและรับผิดชอบงานตามที่ได้รับมอบหมาย เข้าร่วมกิจกรรมเพื่อสังคมตามที่องค์กรกำหนด ปฏิบัติตามแนวทางการอนุรักษ์สิ่งแวดล้อมขององค์กร   2 (พอใช้): นักศึกษามาสายหรือส่งงานล่าช้าบ้างเป็นครั้งคราว เข้าร่วมกิจกรรมเพื่อสังคมเมื่อถูกร้องขอ ปฏิบัติตามแนวทางการอนุรักษ์สิ่งแวดล้อมไม่สม่ำเสมอ   1 (ต้องปรับปรุง): นักศึกษามาสายหรือส่งงานล่าช้าบ่อยครั้ง ไม่เข้าร่วมกิจกรรมเพื่อสังคม ละเลยการปฏิบัติตามแนวทางการอนุรักษ์สิ่งแวดล้อม', NULLIF('', ''), NULLIF('LO8', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีความกตัญญู ซื่อสัตย์ และปฏิบัติตามกฎระเบียบด้านการท่องเที่ยวและการโรงแรม และสังคม |   5 (ยอดเยี่ยม): นักศึกษาปฏิบัติตามกฎระเบียบขององค์กรอย่างเคร่งครัดและสม่ำเสมอ รายงานข้อมูลและนำส่งทรัพย์สิน/เงินอย่างถูกต้องครบถ้วนทุกครั้ง แสดงความเคารพและให้เกียรติผู้อื่นอย่างสม่ำเสมอ เป็นแบบอย่างที่ดีให้เพื่อนร่วมงาน   4 (ดีมาก): นักศึกษาปฏิบัติตามกฎระเบียบขององค์กรอย่างสม่ำเสมอ รายงานข้อมูลและนำส่งทรัพย์สิน/เงินอย่างถูกต้อง แสดงความเคารพและให้เกียรติผู้อื่นเป็นประจำ ได้รับความไว้วางใจจากผู้ร่วมงาน   3 (ดี): นักศึกษาปฏิบัติตามกฎระเบียบขององค์กรเป็นส่วนใหญ่ รายงานข้อมูลและนำส่งทรัพย์สิน/เงินโดยมีข้อผิดพลาดเล็กน้อย แสดงความเคารพและให้เกียรติผู้อื่น ไม่มีข้อร้องเรียนด้านความซื่อสัตย์   2 (พอใช้): นักศึกษามีการละเลยการปฏิบัติตามกฎระเบียบบ้าง มีข้อผิดพลาดในการรายงานข้อมูลและนำส่งทรัพย์สิน/เงิน ขาดความเคารพหรือให้เกียรติผู้อื่นบางครั้ง ต้องได้รับการตักเตือนด้านความประพฤติ   1 (ต้องปรับปรุง): นักศึกษาละเลยการปฏิบัติตามกฎระเบียบบ่อยครั้ง มีปัญหาด้านความซื่อสัตย์ในการรายงานหรือนำส่งทรัพย์สิน ขาดความเคารพหรือให้เกียรติผู้อื่นบ่อยครั้ง มีข้อร้องเรียนด้านความประพฤติ', NULLIF('', ''), NULLIF('LO9', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': แสดงออกถึงการอนุรักษ์ทรัพยากรธรรมชาติและวัฒนธรรมเพื่อลดผลกระทบที่เกิดขึ้นต่อ เศรษฐกิจ สังคม และสิ่งแวดล้อม |   5 (ยอดเยี่ยม): นักศึกษาริเริ่มหรือมีส่วนร่วมในโครงการอนุรักษ์สิ่งแวดล้อมและวัฒนธรรมท้องถิ่น นำเสนอแนวทางลดผลกระทบต่อสิ่งแวดล้อมที่สามารถนำไปปฏิบัติได้จริง สื่อสารและสร้างความตระหนักด้านการอนุรักษ์แก่ลูกค้าและผู้ร่วมงาน ปฏิบัติตามหลักการท่องเที่ยวอย่างยั่งยืนอย่างสม่ำเสมอ   4 (ดีมาก): นักศึกษาเข้าร่วมกิจกรรมอนุรักษ์สิ่งแวดล้อมและวัฒนธรรมท้องถิ่นอย่างสม่ำเสมอ ปฏิบัติตามแนวทางลดผลกระทบต่อสิ่งแวดล้อมอย่างเคร่งครัด ให้ข้อมูลด้านการอนุรักษ์แก่ลูกค้าได้อย่างถูกต้อง คำนึงถึงผลกระทบต่อสิ่งแวดล้อมในการทำงาน   3 (ดี): นักศึกษาเข้าร่วมกิจกรรมอนุรักษ์ตามที่องค์กรกำหนด ปฏิบัติตามแนวทางลดผลกระทบต่อสิ่งแวดล้อมได้ดี เข้าใจและสามารถอธิบายความสำคัญของการอนุรักษ์ ไม่สร้างผลกระทบเชิงลบต่อสิ่งแวดล้อมและวัฒนธรรม   2 (พอใช้): นักศึกษาเข้าร่วมกิจกรรมอนุรักษ์เมื่อถูกร้องขอ ปฏิบัติตามแนวทางลดผลกระทบต่อสิ่งแวดล้อมไม่สม่ำเสมอ มีความเข้าใจด้านการอนุรักษ์ในระดับพื้นฐาน ขาดความใส่ใจต่อผลกระทบด้านสิ่งแวดล้อมบางครั้ง   1 (ต้องปรับปรุง): นักศึกษาไม่สนใจเข้าร่วมกิจกรรมอนุรักษ์ ละเลยการปฏิบัติตามแนวทางลดผลกระทบต่อสิ่งแวดล้อม ขาดความเข้าใจด้านการอนุรักษ์ สร้างผลกระทบเชิงลบต่อสิ่งแวดล้อมและวัฒนธรรม (4)', NULLIF('', ''), NULLIF('LO10', ''), 'single_choice'::question_type, true, 3)
  RETURNING id INTO q_id;
  -- Section: ด้านลักษณะบุคคล
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านลักษณะบุคคล', NULLIF('', ''), 'character'::domain_type, 8)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': แสดงออกถึงการมีจิตบริการ และบุคลิกภาพด้านการแต่งกายและการพูดในงานบริการด้านการท่องเที่ยวและการโรงแรมที่เหมาะสม |   5 (ยอดเยี่ยม): นักศึกษาแต่งกายสุภาพเรียบร้อย ถูกระเบียบทุกครั้ง ให้บริการด้วยความกระตือรือร้น เต็มใจ และเป็นมิตร ได้รับคำชมเชยจากลูกค้าหรือผู้ร่วมงานเป็นประจำ   4 (ดีมาก): นักศึกษาแต่งกายสุภาพเรียบร้อยเกือบทุกครั้ง ให้บริการด้วยความเต็มใจและเป็นมิตร ได้รับคำชมเชยจากลูกค้าหรือผู้ร่วมงานบ่อยครั้ง   3 (ดี): นักศึกษาแต่งกายถูกระเบียบเป็นส่วนใหญ่ ให้บริการตามมาตรฐานที่กำหนด ไม่มีข้อร้องเรียนจากลูกค้าหรือผู้ร่วมงาน   2 (พอใช้): นักศึกษาแต่งกายไม่เรียบร้อยบ้างเป็นครั้งคราว ให้บริการไม่สม่ำเสมอ มีข้อร้องเรียนจากลูกค้าหรือผู้ร่วมงานบ้าง   1 (ต้องปรับปรุง): นักศึกษาแต่งกายไม่เหมาะสมบ่อยครั้ง ให้บริการไม่เต็มใจ หรือแสดงกิริยาไม่เหมาะสม มีข้อร้องเรียนจากลูกค้าหรือผู้ร่วมงานบ่อยครั้ง', NULLIF('', ''), NULLIF('LO11', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': แสดงออกถึงการมีวินัย มีภาวะผู้นำ สามารถเป็นได้ทั้งผู้นำ และผู้ตาม ทำงานร่วมกับผู้อื่นได้ มีจิตอาสา และสามารถพัฒนาตนเองในงานด้านการท่องเที่ยวและการโรงแรมได้อย่างต่อเนื่อง |   5 (ยอดเยี่ยม): นักศึกษาแสดงภาวะผู้นำในการทำงานกลุ่ม รับฟังความคิดเห็นของผู้อื่นและประสานงานได้ดีเยี่ยม มีจิตอาสาช่วยเหลืองานส่วนรวมสม่ำเสมอ   4 (ดีมาก): นักศึกษาสามารถเป็นได้ทั้งผู้นำและผู้ตามที่ดี ประสานงานกับผู้อื่นได้ดี มีจิตอาสาช่วยเหลืองานส่วนรวมบ่อยครั้ง   3 (ดี): นักศึกษาทำหน้าที่ผู้นำหรือผู้ตามได้ตามที่ได้รับมอบหมาย ทำงานร่วมกับผู้อื่นได้ดี มีจิตอาสาช่วยเหลืองานส่วนรวมเมื่อมีโอกาส   2 (พอใช้): นักศึกษาไม่ค่อยแสดงบทบาทผู้นำ ทำงานร่วมกับผู้อื่นได้แต่มีข้อจำกัด ช่วยเหลืองานส่วนรวมเมื่อถูกร้องขอ   1 (ต้องปรับปรุง): นักศึกษาไม่สามารถเป็นผู้นำหรือผู้ตามที่ดีได้ มีปัญหาในการทำงานร่วมกับผู้อื่น ไม่มีจิตอาสาช่วยเหลืองานส่วนรวม', NULLIF('', ''), NULLIF('LO12', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
END $$;

DO $$ DECLARE t_id uuid; s_id uuid; q_id uuid; BEGIN
  -- Create template
  INSERT INTO public.evaluation_templates (program_id, name, title_en, status, status_enum, version_label, source_document_id, extraction_confidence, needs_review)
  SELECT sd.program_id, 'หลักสูตรบริหารธุรกิจบัณฑิต', NULLIF('', ''), 'draft', 'draft'::assessment_status, '0.1', sd.id, 1.0, true
  FROM public.assessment_source_documents sd WHERE sd.filename = 'แบบประเมินสหกิจฯ สาขาการจัดการการท่องเที่ยวและการโรงแรม (updated 30 Jan 2025).pdf'
  RETURNING id INTO t_id;
  IF t_id IS NULL THEN RETURN; END IF;
  -- Section: ด้านความรู้ (Knowledge)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านความรู้ (Knowledge)', NULLIF('', ''), 'knowledge'::domain_type, 1)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ประยุกต์ความรู้ด้านบริหารธุรกิจและการจัดการ 5 (ยอดเยี่ยม): นักศึกษาสามารถวิเคราะห์สถานการณ์ นวัตกรรมเพื่อการด าเนินงานด้านการท่องเที่ยวและ และเสนอแนวทางแก้ไขปัญหาโดยใช้หลักการบริหารธุรกิจ การโรงแรม ได้อย่างเป็นระบบ น าเสนอนวัตกรรมหรือแนวคิดใหม่ๆ ที่ สามารถน าไปใช้ได้จริงในองค์กร มีการบูรณาการความรู้ จากหลายศาสตร์มาประยุกต์ใช้ได้อย่างเหมาะสม', NULLIF('', ''), NULLIF('LO1', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('', ''), NULLIF('นักศึกษาสามารถประยุกต์ใช้หลักการ บริหารธุรกิจในการท างานได้ดี มีการน าเสนอแนวคิดใหม่ๆ ในการพัฒนางาน เข้าใจและเชื่อมโยงทฤษฎีสู่การปฏิบัติได้', ''), 4, 1);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('', ''), NULLIF('นักศึกษาเข้าใจหลักการบริหารธุรกิจพื้นฐาน และน ามาใช้ในงานได้ ท างานตามกระบวนการมาตรฐาน ขององค์กรได้ดี รู้จักปรับปรุงวิธีการท างานเมื่อได้รับ ค าแนะน า', ''), 3, 2);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', NULLIF('', ''), NULLIF('นักศึกษาเข้าใจหลักการพื้นฐานแต่ ประยุกต์ใช้ได้จ ากัด ต้องได้รับค าแนะน าในการท างาน บ่อยครั้ง ท างานตามที่ได้รับมอบหมายได้แต่ขาดการริเริ่ม', ''), 2, 3);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('', ''), NULLIF('นักศึกษาไม่สามารถน าความรู้มา ประยุกต์ใช้ในงานได้ ไม่เข้าใจหลักการพื้นฐานที่จ าเป็น ต้อง ได้รับการก ากับดูแลอย่างใกล้ชิดตลอดเวลา (5) LO2: ประยุกต์ความรู้การจัดการการท่องเที่ยวและ 5 (ยอดเยี่ยม): นักศึกษาสามารถจัดการงานบริการได้ การโรงแรมเพื่อการปฏิบัติงานด้านการท่องเที่ยวและ อย่างมีประสิทธิภาพสูง โดยได้รับความพึงพอใจจากลูกค้า การโรงแรม > 90% แก้ไขสถานการณ์เฉพาะหน้าได้อย่างเหมาะสมและ รวดเร็ว สามารถสอนงานหรือแนะน าเพื่อนร่วมงานได้', ''), 1, 4);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('', ''), NULLIF('นักศึกษาสามารถจัดการงานบริการได้ดี ได้รับความพึงพอใจจากลูกค้า 80-90% แก้ไขปัญหาพื้นฐาน ในงานบริการได้ด้วยตนเอง มีการวางแผนและจัดล าดับ ความส าคัญของงานได้ดี', ''), 4, 5);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('', ''), NULLIF('นักศึกษาสามารถให้บริการตามมาตรฐานได้ดี ได้รับความพึงพอใจจากลูกค้า 70-79% ท างานตามขั้นตอน ที่ก าหนดได้ครบถ้วน สื่อสารกับลูกค้าและเพื่อนร่วมงานได้ อย่างเหมาะสม', ''), 3, 6);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', NULLIF('', ''), NULLIF('นักศึกษาสามารถให้บริการได้ตาม มาตรฐานขั้นต่ า ได้รับความพึงพอใจจากลูกค้า 60-69% ต้องได้รับค าแนะน าในการแก้ไขปัญหาเสมอ การสื่อสารกับ ลูกค้ายังมีข้อบกพร่อง', ''), 2, 7);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('', ''), NULLIF('ไม่สามารถให้บริการตามมาตรฐาน ขั้นต่ า ได้รับความพึงพอใจจากลูกค้า < 60% ไม่สามารถ แก้ไขปัญหาพื้นฐานได้ มีปัญหาในการสื่อสารกับลูกค้าและ เพื่อนร่วมงาน (6) (2)', ''), 1, 8);
