  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีทักษะการสื่อสารภาษาไทย และภาษาอังกฤษ 5 (ยอดเยี่ยม): นักศึกษาสามารถสื่อสารภาษาไทยและ เพื่อใช้ในชีวิตประจ าวันและในการท างานด้านการ ภาษาอังกฤษได้อย่างคล่องแคล่วทั้งการฟัง พูด อ่าน เขียน ท่องเที่ยวและการโรงแรมทั้งการฟัง พูด อ่าน เขียน สามารถน าเสนองานเป็นภาษาอังกฤษได้อย่างมี และน าเสนอผลงานได้อย่างเหมาะสมกับ สถานการณ์ ประสิทธิภาพ กรณีเลือกภาษาจีน: สื่อสารในชีวิตประจ าวัน ในกรณีนักศึกษาเลือกภาษาจีน สามารถสื่อสาร และงานบริการได้อย่างคล่องแคล่ว ภาษาจีน ในชีวิตประจ าวันได้', NULLIF('', ''), NULLIF('LO3', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('', ''), NULLIF('นักศึกษาสามารถสื่อสารภาษาไทยได้ดีมาก และภาษาอังกฤษได้ดี น าเสนองานเป็นภาษาอังกฤษได้ โดย มีข้อผิดพลาดเล็กน้อย กรณีเลือกภาษาจีน: สื่อสารใน ชีวิตประจ าวันได้ดี มีข้อผิดพลาดน้อย', ''), 4, 1);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('', ''), NULLIF('นักศึกษาสามารถสื่อสารภาษาไทยได้ดี และ ภาษาอังกฤษได้ในระดับใช้งาน น าเสนองานเป็น ภาษาอังกฤษได้ แต่ต้องเตรียมตัวมาก กรณีเลือกภาษาจีน: สื่อสารประโยคพื้นฐานในชีวิตประจ าวันได้', ''), 3, 2);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', NULLIF('', ''), NULLIF('นักศึกษาสามารถสื่อสารภาษาไทยได้พอใช้ ภาษาอังกฤษมีข้อจ ากัด ต้องได้รับความช่วยเหลือในการ น าเสนองานภาษาอังกฤษ กรณีเลือกภาษาจีน: สื่อสารได้ เฉพาะประโยคง่ายๆ', ''), 2, 3);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('', ''), NULLIF('นักศึกษามีปัญหาในการสื่อสารทั้ง ภาษาไทยและภาษาอังกฤษ ไม่สามารถน าเสนองานเป็น ภาษาอังกฤษได้ กรณีเลือกภาษาจีน: ไม่สามารถสื่อสาร ภาษาจีนได้แม้แต่ประโยคพื้นฐาน', ''), 1, 4);
