  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('', ''), NULLIF('นักศึกษาไม่สามารถจัดกิจกรรม นันทนาการได้แม้จะมีผู้แนะน า มีปัญหาในการให้บริการ บ่อยครั้ง ได้รับความพึงพอใจจากลูกค้าในระดับต่ า (<60%)', ''), 1, 5);
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีทักษะการออกแบบประสบการณ์การ 5 (ยอดเยี่ยม): นักศึกษาสามารถออกแบบโปรแกรม ท่องเที่ยวแก่ลูกค้าในแหล่งท่องเที่ยวและโรงแรม การท่องเที่ยวที่สร้างสรรค์และตอบโจทย์ความต้องการของ ลูกค้าได้ดีเยี่ยม บูรณาการทรัพยากรการท่องเที่ยวและ บริการต่างๆ ได้อย่างลงตัว น าเสนอประสบการณ์ที่แปลก ใหม่และน่าประทับใจ พร้อมค านึงถึงความยั่งยืน', NULLIF('', ''), NULLIF('LO7', ''), 'single_choice'::question_type, true, 5)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('', ''), NULLIF('นักศึกษาสามารถออกแบบโปรแกรมการ ท่องเที่ยวที่น่าสนใจและตอบสนองความต้องการของลูกค้า จัดการทรัพยากรการท่องเที่ยวและบริการได้อย่างมี ประสิทธิภาพ สร้างประสบการณ์ที่น่าจดจ าให้กับลูกค้าได้', ''), 4, 1);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('', ''), NULLIF('นักศึกษาสามารถออกแบบโปรแกรมการ ท่องเที่ยวตามมาตรฐานได้ จัดการทรัพยากรการท่องเที่ยว และบริการได้ตามแผน น าเสนอประสบการณ์ที่เหมาะสม กับกลุ่มลูกค้า', ''), 3, 2);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', NULLIF('', ''), NULLIF('นักศึกษาสามารถออกแบบโปรแกรมการ ท่องเที่ยวได้แต่ต้องมีผู้แนะน า จัดการทรัพยากรการ ท่องเที่ยวและบริการได้แต่มีข้อบกพร่อง น าเสนอ ประสบการณ์แบบพื้นฐานได้', ''), 2, 3);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('', ''), NULLIF('นักศึกษาไม่สามารถออกแบบ โปรแกรมการท่องเที่ยวได้แม้มีผู้แนะน า มีปัญหาในการ จัดการทรัพยากรการท่องเที่ยวและบริการ ไม่สามารถ น าเสนอประสบการณ์ที่น่าพอใจให้กับลูกค้า (3)', ''), 1, 4);
  -- Section: ด้านจริยธรรม (Ethics)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านจริยธรรม (Ethics)', NULLIF('', ''), 'ethics'::domain_type, 3)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีความรับผิดชอบต่อตนเอง สังคม และ 5 (ยอดเยี่ยม): นักศึกษามีความตรงต่อเวลาและ สิ่งแวดล้อม รับผิดชอบงานอย่างสม่ าเสมอ มีส่วนร่วมในกิจกรรมเพื่อ สังคมขององค์กรอย่างกระตือรือร้น ริเริ่มและน าเสนอแนว ทางการอนุรักษ์สิ่งแวดล้อมในการท างาน', NULLIF('', ''), NULLIF('LO8', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('', ''), NULLIF('นักศึกษามีความตรงต่อเวลาและรับผิดชอบ งานเป็นอย่างดี เข้าร่วมกิจกรรมเพื่อสังคมขององค์กรอย่าง สม่ าเสมอ ปฏิบัติตามแนวทางการอนุรักษ์สิ่งแวดล้อมของ องค์กรอย่างเคร่งครัด', ''), 4, 1);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('', ''), NULLIF('นักศึกษามีความตรงต่อเวลาและรับผิดชอบงาน ตามที่ได้รับมอบหมาย เข้าร่วมกิจกรรมเพื่อสังคมตามที่ องค์กรก าหนด ปฏิบัติตามแนวทางการอนุรักษ์สิ่งแวดล้อม ขององค์กร', ''), 3, 2);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช', NULLIF('', ''), NULLIF('้ : นักศึกษามาสายหรือส่งงานล่าช้าบ้างเป็น ครั้งคราว เข้าร่วมกิจกรรมเพื่อสังคมเมื่อถูกร้องขอ ปฏิบัติ ตามแนวทางการอนุรักษ์สิ่งแวดล้อมไม่สม่ าเสมอ', ''), 2, 3);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('', ''), NULLIF('นักศึกษามาสายหรือส่งงานล่าช้า บ่อยครั้ง ไม่เข้าร่วมกิจกรรมเพื่อสังคม ละเลยการปฏิบัติ ตามแนวทางการอนุรักษ์สิ่งแวดล้อม', ''), 1, 4);
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีความกตัญญู ซื่อสัตย์ และปฏิบัติตาม 5 (ยอดเยี่ยม): นักศึกษาปฏิบัติตามกฎระเบียบของ กฎระเบียบด้านการท่องเที่ยวและการโรงแรม และ องค์กรอย่างเคร่งครัดและสม่ าเสมอ รายงานข้อมูลและ สังคม น าส่งทรัพย์สิน/เงินอย่างถูกต้องครบถ้วนทุกครั้ง แสดง ความเคารพและให้เกียรติผู้อื่นอย่างสม่ าเสมอ เป็น แบบอย่างที่ดีให้เพื่อนร่วมงาน', NULLIF('', ''), NULLIF('LO9', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('', ''), NULLIF('นักศึกษาปฏิบัติตามกฎระเบียบขององค์กร อย่างสม่ าเสมอ รายงานข้อมูลและน าส่งทรัพย์สิน/เงินอย่าง ถูกต้อง แสดงความเคารพและให้เกียรติผู้อื่นเป็นประจ า ได้รับความไว้วางใจจากผู้ร่วมงาน', ''), 4, 1);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('', ''), NULLIF('นักศึกษาปฏิบัติตามกฎระเบียบขององค์กรเป็น ส่วนใหญ่ รายงานข้อมูลและน าส่งทรัพย์สิน/เงินโดยมี ข้อผิดพลาดเล็กน้อย แสดงความเคารพและให้เกียรติผู้อื่น ไม่มีข้อร้องเรียนด้านความซื่อสัตย์', ''), 3, 2);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', NULLIF('', ''), NULLIF('นักศึกษามีการละเลยการปฏิบัติตาม กฎระเบียบบ้าง มีข้อผิดพลาดในการรายงานข้อมูลและ น าส่งทรัพย์สิน/เงิน ขาดความเคารพหรือให้เกียรติผู้อื่น บางครั้ง ต้องได้รับการตักเตือนด้านความประพฤติ', ''), 2, 3);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('', ''), NULLIF('นักศึกษาละเลยการปฏิบัติตาม กฎระเบียบบ่อยครั้ง มีปัญหาด้านความซื่อสัตย์ในการ รายงานหรือน าส่งทรัพย์สิน ขาดความเคารพหรือให้เกียรติ ผู้อื่นบ่อยครั้ง มีข้อร้องเรียนด้านความประพฤติ', ''), 1, 4);
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': แสดงออกถึงการอนุรักษ์ทรัพยากรธรรมชาติ 5 (ยอดเยี่ยม): นักศึกษาริเริ่มหรือมีส่วนร่วมใน และวัฒนธรรมเพื่อลดผลกระทบที่เกิดขึ้นต่อ เศรษฐกิจ โครงการอนุรักษ์สิ่งแวดล้อมและวัฒนธรรมท้องถิ่น น าเสนอ สังคม และสิ่งแวดล้อม แนวทางลดผลกระทบต่อสิ่งแวดล้อมที่สามารถน าไปปฏิบัติ ได้จริง สื่อสารและสร้างความตระหนักด้านการอนุรักษ์แก่ ลูกค้าและผู้ร่วมงาน ปฏิบัติตามหลักการท่องเที่ยวอย่าง ยั่งยืนอย่างสม่ าเสมอ', NULLIF('', ''), NULLIF('LO10', ''), 'single_choice'::question_type, true, 3)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('', ''), NULLIF('นักศึกษาเข้าร่วมกิจกรรมอนุรักษ์ สิ่งแวดล้อมและวัฒนธรรมท้องถิ่นอย่างสม่ าเสมอ ปฏิบัติ ตามแนวทางลดผลกระทบต่อสิ่งแวดล้อมอย่างเคร่งครัด ให้ ข้อมูลด้านการอนุรักษ์แก่ลูกค้าได้อย่างถูกต้อง ค านึงถึง ผลกระทบต่อสิ่งแวดล้อมในการท างาน', ''), 4, 1);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('', ''), NULLIF('นักศึกษาเข้าร่วมกิจกรรมอนุรักษ์ตามที่องค์กร ก าหนด ปฏิบัติตามแนวทางลดผลกระทบต่อสิ่งแวดล้อมได้', ''), 3, 2);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดี', NULLIF('Good', ''), NULLIF('เข้าใจและสามารถอธิบายความส าคัญของการอนุรักษ์ ไม่ สร้างผลกระทบเชิงลบต่อสิ่งแวดล้อมและวัฒนธรรม', ''), 3, 3);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', NULLIF('', ''), NULLIF('นักศึกษาเข้าร่วมกิจกรรมอนุรักษ์เมื่อถูก ร้องขอ ปฏิบัติตามแนวทางลดผลกระทบต่อสิ่งแวดล้อมไม่ สม่ าเสมอ มีความเข้าใจด้านการอนุรักษ์ในระดับพื้นฐาน ขาดความใส่ใจต่อผลกระทบด้านสิ่งแวดล้อมบางครั้ง', ''), 2, 4);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('', ''), NULLIF('นักศึกษาไม่สนใจเข้าร่วมกิจกรรม อนุรักษ ์ ละเลยการปฏิบัติตามแนวทางลดผลกระทบต่อ สิ่งแวดล้อม ขาดความเข้าใจด้านการอนุรักษ์ สร้าง ผลกระทบเชิงลบต่อสิ่งแวดล้อมและวัฒนธรรม (4)', ''), 1, 5);
