  VALUES (t_id, s_id, ': แสดงออกถึงการมีจิตบริการ และบุคลิกภาพ 5 (ยอดเยี่ยม): นักศึกษาแต่งกายสุภาพเรียบร้อย ถูก ระเบียบทุกครั้ง ให้บริการด้วยความกระตือรือร้น เต็มใจ ท่องเที่ยวและการโรงแรมที่เหมาะสม และเป็นมิตร ได้รับค าชมเชยจากลูกค้าหรือผู้ร่วมงานเป็น ประจ า', NULLIF('', ''), NULLIF('LO11', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('', ''), NULLIF('นักศึกษาแต่งกายสุภาพเรียบร้อยเกือบทุก ครั้ง ให้บริการด้วยความเต็มใจและเป็นมิตร ได้รับค าชมเชย จากลูกค้าหรือผู้ร่วมงานบ่อยครั้ง', ''), 4, 1);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
