  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', NULLIF('', ''), NULLIF('นักศึกษาแต่งกายไม่เรียบร้อยบ้างเป็นครั้ง คราว ให้บริการไม่สม่ าเสมอ มีข้อร้องเรียนจากลูกค้าหรือ ผู้ร่วมงานบ้าง', ''), 2, 3);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ต้องปรับปรุง', NULLIF('', ''), NULLIF('นักศึกษาแต่งกายไม่เหมาะสม บ่อยครั้ง ให้บริการไม่เต็มใจ หรือแสดงกิริยาไม่เหมาะสม มี ข้อร้องเรียนจากลูกค้าหรือผู้ร่วมงานบ่อยครั้ง', ''), 1, 4);
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': แสดงออกถึงการมีวินัย มีภาวะผู้น า สามารถ 5 (ยอดเยี่ยม): นักศึกษาแสดงภาวะผู้น าในการท างาน เป็นได้ทั้งผู้น า และผู้ตาม ท างานร่วมกับผู้อื่นได้ มีจิต กลุ่ม รับฟังความคิดเห็นของผู้อื่นและประสานงานได้ดีเยี่ยม อาสา และสามารถพัฒนาตนเองในงานด้านการ มีจิตอาสาช่วยเหลืองานส่วนรวมสม่ าเสมอ ท่องเที่ยวและการโรงแรมได้อย่างต่อเนื่อง', NULLIF('', ''), NULLIF('LO12', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'ดีมาก', NULLIF('', ''), NULLIF('นักศึกษาสามารถเป็นได้ทั้งผู้น าและผู้ตามที่', ''), 4, 1);
